insert into grade9_term1_reconstructed_content(
  item_code, definition_code, display_order, skill_code, prompt, answer_config,
  solution, difficulty, reasoning_classification, cognitive_level, representation
) values
  ('Q.G9.T1C.WHOLE.TOPIC-BASELINE.1', 'G9-T1-WHOLE-MASTERY-TOPIC-BASELINE', 1, 'G9-NUM-REAL-IRRATIONAL', 'Which statement correctly classifies √49?', '{"type":"multiple_choice","options":{"A":"It is the negative integer −7.","B":"7 is a natural number, an integer and a rational number.","C":"It is irrational because it is written with a root sign.","D":"It is not real because square roots are not numbers."},"correct_option":"B","distractor_explanations":{"A":"√ denotes the principal, non-negative square root.","C":"The radicand is a perfect square, so its square root is an integer.","D":"The square root of a positive number is real."}}', '√49 = 7. Every natural number is also an integer and rational.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.WHOLE.TOPIC-BASELINE.2', 'G9-T1-WHOLE-MASTERY-TOPIC-BASELINE', 2, 'G9-NUM-REAL-IRRATIONAL', 'Which number is irrational in this number set 1?', '{"type":"multiple_choice","options":{"A":"√18","B":"√49","C":"0.125","D":"−3/8"},"correct_option":"A","distractor_explanations":{"B":"√49 is an integer and is therefore rational.","C":"A terminating decimal is rational.","D":"A ratio of integers with a non-zero denominator is rational."}}', '18 is not a perfect square, so √18 cannot be written as a ratio of integers. The other three numbers are rational.', 2, 'mathematical_reasoning', 'complex', 'verbal'),
  ('Q.G9.T1C.WHOLE.TOPIC-BASELINE.3', 'G9-T1-WHOLE-MASTERY-TOPIC-BASELINE', 3, 'G9-NUM-WHOLE-HCF-LCM', 'What is the prime factorisation of 60?', '{"type":"multiple_choice","options":{"A":"2^1 × 3 × 5","B":"2^2 × 3² × 5","C":"2^3 × 3 × 5","D":"2^2 × 3 × 5"},"correct_option":"D","distractor_explanations":{"A":"This omits one factor of 2.","B":"This introduces an extra factor of 3.","C":"This introduces an extra factor of 2."}}', '60 = 4 × 15 = 2^2 × 3 × 5.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.WHOLE.TOPIC-BASELINE.4', 'G9-T1-WHOLE-MASTERY-TOPIC-BASELINE', 4, 'G9-NUM-WHOLE-HCF-LCM', 'Determine the HCF of 12 and 18.', '{"type":"multiple_choice","options":{"A":"12","B":"18","C":"6","D":"2"},"correct_option":"C","distractor_explanations":{"A":"This is one of the numbers, not a factor of 18.","B":"This is one of the numbers, not a factor of 12.","D":"This is common, but not the highest common factor."}}', '12 = 2 × 3 × 2 and 18 = 3² × 2. The common factors give 3 × 2 = 6.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.WHOLE.TOPIC-BASELINE.5', 'G9-T1-WHOLE-MASTERY-TOPIC-BASELINE', 5, 'G9-NUM-WHOLE-HCF-LCM', 'Two bells ring every 8 and 12 minutes. After how many minutes will they next ring together?', '{"type":"multiple_choice","options":{"A":"48","B":"24","C":"4","D":"20"},"correct_option":"B","distractor_explanations":{"A":"This doubles the LCM unnecessarily.","C":"This is the HCF, not the first common multiple.","D":"This is not divisible by both intervals."}}', 'LCM(8, 12) = LCM(2² × 2, 2 × 3 × 2) = 2² × 3 × 2 = 24.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.WHOLE.TOPIC-BASELINE.6', 'G9-T1-WHOLE-MASTERY-TOPIC-BASELINE', 6, 'G9-NUM-RATIO-RATE', 'A fruit drink uses 4:3 cups of juice to water. How many cups of water are needed for 8 cups of juice?', '{"type":"multiple_choice","options":{"A":"6","B":"3","C":"8","D":"12"},"correct_option":"A","distractor_explanations":{"B":"This keeps the original water amount instead of scaling it.","C":"This repeats the juice amount as water.","D":"This multiplies the water by the juice amount rather than by the scale factor."}}', 'The juice amount doubles from 4 to 8. Water must also double: 3 × 2 = 6 cups.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.WHOLE.TOPIC-BASELINE.7', 'G9-T1-WHOLE-MASTERY-TOPIC-BASELINE', 7, 'G9-NUM-RATIO-RATE', 'A cyclist travels 30 km in 2 hours at a constant speed. What is the unit rate?', '{"type":"multiple_choice","options":{"A":"32 km/h","B":"28 km/h","C":"60 km/h","D":"15 km/h"},"correct_option":"D","distractor_explanations":{"A":"This adds distance and time instead of dividing.","B":"This subtracts rather than finding a unit rate.","C":"This multiplies distance by time instead of dividing."}}', 'Speed = distance ÷ time = 30 ÷ 2 = 15 km/h.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.WHOLE.TOPIC-BASELINE.8', 'G9-T1-WHOLE-MASTERY-TOPIC-BASELINE', 8, 'G9-NUM-DIRECT-INVERSE-PROPORTION', 'Five identical notebooks cost R45. At the same price per notebook, what do eight notebooks cost?', '{"type":"multiple_choice","options":{"A":"R360","B":"R9","C":"R72","D":"R53"},"correct_option":"C","distractor_explanations":{"A":"This multiplies the total for five notebooks by eight.","B":"This is the unit price, not the price of eight notebooks.","D":"This adds the number of notebooks to the price."}}', 'One notebook costs R45 ÷ 5 = R9. Eight cost 8 × R9 = R72.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.WHOLE.TOPIC-BASELINE.9', 'G9-T1-WHOLE-MASTERY-TOPIC-BASELINE', 9, 'G9-NUM-DIRECT-INVERSE-PROPORTION', 'Four workers complete a job in 6 days at the same rate. How many days would eight workers take?', '{"type":"multiple_choice","options":{"A":"24 days","B":"3 days","C":"12 days","D":"6 days"},"correct_option":"B","distractor_explanations":{"A":"This gives worker-days rather than days for eight workers.","C":"This treats days as directly proportional to workers.","D":"This ignores the increase in workers."}}', 'The job needs 4 × 6 = 24 worker-days. With 8 workers: 24 ÷ 8 = 3 days.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.WHOLE.TOPIC-BASELINE.10', 'G9-T1-WHOLE-MASTERY-TOPIC-BASELINE', 10, 'G9-NUM-FINANCIAL-APPLICATIONS', 'A salesperson earns 6% commission on sales of R1000. What is the commission?', '{"type":"multiple_choice","options":{"A":"R600","B":"R1006","C":"R6","D":"R60"},"correct_option":"D","distractor_explanations":{"A":"This uses 60% instead of 6%.","B":"This adds 6 rand instead of taking 6%.","C":"This uses 0.6% instead of 6%."}}', '6% = 0.06. Commission = 0.06 × R1000 = R60.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.WHOLE.TOPIC-BASELINE.11', 'G9-T1-WHOLE-MASTERY-TOPIC-BASELINE', 11, 'G9-NUM-FINANCIAL-APPLICATIONS', 'A bicycle rental costs R45 per day plus a once-off R20 deposit. What is paid at collection for 3 days?', '{"type":"multiple_choice","options":{"A":"R195","B":"R65","C":"R155","D":"R135"},"correct_option":"C","distractor_explanations":{"A":"This charges the once-off deposit three times.","B":"This includes only one rental day.","D":"This omits the once-off deposit."}}', 'Rental = 3 × R45 = R135. Add one deposit of R20: R155.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.WHOLE.TOPIC-BASELINE.12', 'G9-T1-WHOLE-MASTERY-TOPIC-BASELINE', 12, 'G9-NUM-FINANCIAL-APPLICATIONS', 'R1200 is invested at 10% compound interest per year. What is the balance after two years?', '{"type":"multiple_choice","options":{"A":"R1462.00","B":"R1452.00","C":"R1440.00","D":"R1320.00"},"correct_option":"B","distractor_explanations":{"A":"This adds an extra R10 after compounding.","C":"This adds simple interest for two years.","D":"This stops after one year."}}', 'After year 1: R1200 × 1.10 = R1320.00. After year 2: R1320.00 × 1.10 = R1452.00.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.WHOLE.ENDLINE.1', 'G9-T1-WHOLE-MASTERY-ENDLINE', 1, 'G9-NUM-REAL-IRRATIONAL', 'Which statement correctly classifies √64?', '{"type":"multiple_choice","options":{"A":"It is irrational because it is written with a root sign.","B":"It is not real because square roots are not numbers.","C":"It is the negative integer −8.","D":"8 is a natural number, an integer and a rational number."},"correct_option":"D","distractor_explanations":{"A":"The radicand is a perfect square, so its square root is an integer.","B":"The square root of a positive number is real.","C":"√ denotes the principal, non-negative square root."}}', '√64 = 8. Every natural number is also an integer and rational.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.WHOLE.ENDLINE.2', 'G9-T1-WHOLE-MASTERY-ENDLINE', 2, 'G9-NUM-REAL-IRRATIONAL', 'Which number is irrational in this number set 2?', '{"type":"multiple_choice","options":{"A":"0.125","B":"−3/8","C":"√12","D":"√64"},"correct_option":"C","distractor_explanations":{"A":"A terminating decimal is rational.","B":"A ratio of integers with a non-zero denominator is rational.","D":"√64 is an integer and is therefore rational."}}', '12 is not a perfect square, so √12 cannot be written as a ratio of integers. The other three numbers are rational.', 2, 'mathematical_reasoning', 'complex', 'verbal'),
  ('Q.G9.T1C.WHOLE.ENDLINE.3', 'G9-T1-WHOLE-MASTERY-ENDLINE', 3, 'G9-NUM-WHOLE-HCF-LCM', 'What is the prime factorisation of 120?', '{"type":"multiple_choice","options":{"A":"2^4 × 3 × 5","B":"2^3 × 3 × 5","C":"2^2 × 3 × 5","D":"2^3 × 3² × 5"},"correct_option":"B","distractor_explanations":{"A":"This introduces an extra factor of 2.","C":"This omits one factor of 2.","D":"This introduces an extra factor of 3."}}', '120 = 8 × 15 = 2^3 × 3 × 5.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.WHOLE.ENDLINE.4', 'G9-T1-WHOLE-MASTERY-ENDLINE', 4, 'G9-NUM-WHOLE-HCF-LCM', 'Determine the HCF of 18 and 27.', '{"type":"multiple_choice","options":{"A":"9","B":"3","C":"18","D":"27"},"correct_option":"A","distractor_explanations":{"B":"This is common, but not the highest common factor.","C":"This is one of the numbers, not a factor of 27.","D":"This is one of the numbers, not a factor of 18."}}', '18 = 2 × 3 × 3 and 27 = 3² × 3. The common factors give 3 × 3 = 9.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.WHOLE.ENDLINE.5', 'G9-T1-WHOLE-MASTERY-ENDLINE', 5, 'G9-NUM-WHOLE-HCF-LCM', 'Two bells ring every 12 and 18 minutes. After how many minutes will they next ring together?', '{"type":"multiple_choice","options":{"A":"6","B":"30","C":"72","D":"36"},"correct_option":"D","distractor_explanations":{"A":"This is the HCF, not the first common multiple.","B":"This is not divisible by both intervals.","C":"This doubles the LCM unnecessarily."}}', 'LCM(12, 18) = LCM(2² × 3, 2 × 3 × 3) = 2² × 3 × 3 = 36.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.WHOLE.ENDLINE.6', 'G9-T1-WHOLE-MASTERY-ENDLINE', 6, 'G9-NUM-RATIO-RATE', 'A fruit drink uses 5:3 cups of juice to water. How many cups of water are needed for 10 cups of juice?', '{"type":"multiple_choice","options":{"A":"10","B":"15","C":"6","D":"3"},"correct_option":"C","distractor_explanations":{"A":"This repeats the juice amount as water.","B":"This multiplies the water by the juice amount rather than by the scale factor.","D":"This keeps the original water amount instead of scaling it."}}', 'The juice amount doubles from 5 to 10. Water must also double: 3 × 2 = 6 cups.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.WHOLE.ENDLINE.7', 'G9-T1-WHOLE-MASTERY-ENDLINE', 7, 'G9-NUM-RATIO-RATE', 'A cyclist travels 45 km in 3 hours at a constant speed. What is the unit rate?', '{"type":"multiple_choice","options":{"A":"135 km/h","B":"15 km/h","C":"48 km/h","D":"42 km/h"},"correct_option":"B","distractor_explanations":{"A":"This multiplies distance by time instead of dividing.","C":"This adds distance and time instead of dividing.","D":"This subtracts rather than finding a unit rate."}}', 'Speed = distance ÷ time = 45 ÷ 3 = 15 km/h.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.WHOLE.ENDLINE.8', 'G9-T1-WHOLE-MASTERY-ENDLINE', 8, 'G9-NUM-DIRECT-INVERSE-PROPORTION', 'Five identical notebooks cost R50. At the same price per notebook, what do eight notebooks cost?', '{"type":"multiple_choice","options":{"A":"R80","B":"R58","C":"R400","D":"R10"},"correct_option":"A","distractor_explanations":{"B":"This adds the number of notebooks to the price.","C":"This multiplies the total for five notebooks by eight.","D":"This is the unit price, not the price of eight notebooks."}}', 'One notebook costs R50 ÷ 5 = R10. Eight cost 8 × R10 = R80.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.WHOLE.ENDLINE.9', 'G9-T1-WHOLE-MASTERY-ENDLINE', 9, 'G9-NUM-DIRECT-INVERSE-PROPORTION', 'Four workers complete a job in 9 days at the same rate. How many days would eight workers take?', '{"type":"multiple_choice","options":{"A":"18 days","B":"9 days","C":"36 days","D":"4.5 days"},"correct_option":"D","distractor_explanations":{"A":"This treats days as directly proportional to workers.","B":"This ignores the increase in workers.","C":"This gives worker-days rather than days for eight workers."}}', 'The job needs 4 × 9 = 36 worker-days. With 8 workers: 36 ÷ 8 = 4.5 days.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.WHOLE.ENDLINE.10', 'G9-T1-WHOLE-MASTERY-ENDLINE', 10, 'G9-NUM-FINANCIAL-APPLICATIONS', 'A salesperson earns 6% commission on sales of R1500. What is the commission?', '{"type":"multiple_choice","options":{"A":"R9","B":"R90","C":"R900","D":"R1506"},"correct_option":"B","distractor_explanations":{"A":"This uses 0.6% instead of 6%.","C":"This uses 60% instead of 6%.","D":"This adds 6 rand instead of taking 6%."}}', '6% = 0.06. Commission = 0.06 × R1500 = R90.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.WHOLE.ENDLINE.11', 'G9-T1-WHOLE-MASTERY-ENDLINE', 11, 'G9-NUM-FINANCIAL-APPLICATIONS', 'A bicycle rental costs R50 per day plus a once-off R30 deposit. What is paid at collection for 3 days?', '{"type":"multiple_choice","options":{"A":"R180","B":"R150","C":"R240","D":"R80"},"correct_option":"A","distractor_explanations":{"B":"This omits the once-off deposit.","C":"This charges the once-off deposit three times.","D":"This includes only one rental day."}}', 'Rental = 3 × R50 = R150. Add one deposit of R30: R180.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.WHOLE.ENDLINE.12', 'G9-T1-WHOLE-MASTERY-ENDLINE', 12, 'G9-NUM-FINANCIAL-APPLICATIONS', 'R1300 is invested at 10% compound interest per year. What is the balance after two years?', '{"type":"multiple_choice","options":{"A":"R1560.00","B":"R1430.00","C":"R1583.00","D":"R1573.00"},"correct_option":"D","distractor_explanations":{"A":"This adds simple interest for two years.","B":"This stops after one year.","C":"This adds an extra R10 after compounding."}}', 'After year 1: R1300 × 1.10 = R1430.00. After year 2: R1430.00 × 1.10 = R1573.00.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.WHOLE.ENDLINE.13', 'G9-T1-WHOLE-MASTERY-ENDLINE', 13, 'G9-NUM-WHOLE-HCF-LCM', 'A learner says the HCF of 24 and 30 is their product. Which correction is valid?', '{"type":"multiple_choice","options":{"A":"HCF is always the smaller of the two numbers.","B":"HCF means the least common multiple of the two numbers.","C":"HCF means the greatest number that divides both; 6 divides both 24 and 30.","D":"HCF means multiply the two numbers and then choose a factor."},"correct_option":"C","distractor_explanations":{"A":"The smaller number need not divide the larger one.","B":"LCM and HCF are different concepts.","D":"The product is not the definition of HCF."}}', '24 = 6 × 4 and 30 = 6 × 5. The common greatest factor is 6.', 2, 'mathematical_reasoning', 'complex', 'verbal'),
  ('Q.G9.T1C.WHOLE.ENDLINE.14', 'G9-T1-WHOLE-MASTERY-ENDLINE', 14, 'G9-NUM-RATIO-RATE', 'Map set 2 has scale 1 cm : 6 km. Which calculation models 8.5 cm on the map?', '{"type":"multiple_choice","options":{"A":"8.5 km","B":"8.5 × 6 = 51 km","C":"8.5 ÷ 6 km","D":"8.5 + 6 km"},"correct_option":"B","distractor_explanations":{"A":"This ignores that 1 cm represents 6 km.","C":"Dividing reverses the scale relationship.","D":"A scale is multiplicative, not additive."}}', 'Each centimetre represents 6 km. Therefore 8.5 cm represents 8.5 × 6 = 51 km.', 2, 'mathematical_reasoning', 'complex', 'verbal'),
  ('Q.G9.T1C.WHOLE.ENDLINE.15', 'G9-T1-WHOLE-MASTERY-ENDLINE', 15, 'G9-NUM-FINANCIAL-APPLICATIONS', 'Why is compound interest on R1100 at 8% for two years greater than simple interest at the same rate?', '{"type":"multiple_choice","options":{"A":"The second year’s interest is calculated on R1188.00, not on R1100.","B":"The percentage becomes 16% in the second year.","C":"Interest is subtracted in the first year and added in the second.","D":"The principal is divided by the rate each year."},"correct_option":"A","distractor_explanations":{"B":"The annual rate remains unchanged.","C":"Both years add interest for a positive investment.","D":"The rate is applied to the growing balance."}}', 'After year 1 the balance is R1100 × 1.08 = R1188.00. Year 2 interest is calculated from that balance.', 2, 'mathematical_reasoning', 'complex', 'verbal'),
  ('Q.G9.T1C.WHOLE.ENDLINE.16', 'G9-T1-WHOLE-MASTERY-ENDLINE', 16, 'G9-NUM-DIRECT-INVERSE-PROPORTION', 'Which situation in set 2 is inverse proportion?', '{"type":"multiple_choice","options":{"A":"At a fixed unit price, buying more pens increases the total cost.","B":"A recipe doubles every ingredient when the number of portions doubles.","C":"A taxi fare rises when more kilometres are travelled at a fixed rate.","D":"For a fixed journey, a faster constant speed gives a shorter travel time."},"correct_option":"D","distractor_explanations":{"A":"Both quantities increase together, so this is direct proportion.","B":"Both quantities increase together, so this is direct proportion.","C":"Distance and fare increase together, so this is direct proportion."}}', 'For a fixed total task, rate × time is constant. Increasing the rate or workers therefore decreases the time.', 2, 'mathematical_reasoning', 'complex', 'verbal'),
  ('Q.G9.T1C.WHOLE.MASTERY-CHALLENGE.1', 'G9-T1-WHOLE-MASTERY-CHALLENGE', 1, 'G9-NUM-REAL-IRRATIONAL', 'Which statement correctly classifies √81?', '{"type":"multiple_choice","options":{"A":"It is the negative integer −9.","B":"9 is a natural number, an integer and a rational number.","C":"It is irrational because it is written with a root sign.","D":"It is not real because square roots are not numbers."},"correct_option":"B","distractor_explanations":{"A":"√ denotes the principal, non-negative square root.","C":"The radicand is a perfect square, so its square root is an integer.","D":"The square root of a positive number is real."}}', '√81 = 9. Every natural number is also an integer and rational.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.WHOLE.MASTERY-CHALLENGE.2', 'G9-T1-WHOLE-MASTERY-CHALLENGE', 2, 'G9-NUM-REAL-IRRATIONAL', 'Which number is irrational in this number set 3?', '{"type":"multiple_choice","options":{"A":"√27","B":"√81","C":"0.125","D":"−3/8"},"correct_option":"A","distractor_explanations":{"B":"√81 is an integer and is therefore rational.","C":"A terminating decimal is rational.","D":"A ratio of integers with a non-zero denominator is rational."}}', '27 is not a perfect square, so √27 cannot be written as a ratio of integers. The other three numbers are rational.', 2, 'mathematical_reasoning', 'complex', 'verbal'),
  ('Q.G9.T1C.WHOLE.MASTERY-CHALLENGE.3', 'G9-T1-WHOLE-MASTERY-CHALLENGE', 3, 'G9-NUM-WHOLE-HCF-LCM', 'What is the prime factorisation of 240?', '{"type":"multiple_choice","options":{"A":"2^3 × 3 × 5","B":"2^4 × 3² × 5","C":"2^5 × 3 × 5","D":"2^4 × 3 × 5"},"correct_option":"D","distractor_explanations":{"A":"This omits one factor of 2.","B":"This introduces an extra factor of 3.","C":"This introduces an extra factor of 2."}}', '240 = 16 × 15 = 2^4 × 3 × 5.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.WHOLE.MASTERY-CHALLENGE.4', 'G9-T1-WHOLE-MASTERY-CHALLENGE', 4, 'G9-NUM-WHOLE-HCF-LCM', 'Determine the HCF of 24 and 36.', '{"type":"multiple_choice","options":{"A":"24","B":"36","C":"12","D":"4"},"correct_option":"C","distractor_explanations":{"A":"This is one of the numbers, not a factor of 36.","B":"This is one of the numbers, not a factor of 24.","D":"This is common, but not the highest common factor."}}', '24 = 2 × 3 × 4 and 36 = 3² × 4. The common factors give 3 × 4 = 12.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.WHOLE.MASTERY-CHALLENGE.5', 'G9-T1-WHOLE-MASTERY-CHALLENGE', 5, 'G9-NUM-WHOLE-HCF-LCM', 'Two bells ring every 16 and 24 minutes. After how many minutes will they next ring together?', '{"type":"multiple_choice","options":{"A":"96","B":"48","C":"8","D":"40"},"correct_option":"B","distractor_explanations":{"A":"This doubles the LCM unnecessarily.","C":"This is the HCF, not the first common multiple.","D":"This is not divisible by both intervals."}}', 'LCM(16, 24) = LCM(2² × 4, 2 × 3 × 4) = 2² × 3 × 4 = 48.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.WHOLE.MASTERY-CHALLENGE.6', 'G9-T1-WHOLE-MASTERY-CHALLENGE', 6, 'G9-NUM-RATIO-RATE', 'A fruit drink uses 6:3 cups of juice to water. How many cups of water are needed for 12 cups of juice?', '{"type":"multiple_choice","options":{"A":"6","B":"3","C":"12","D":"18"},"correct_option":"A","distractor_explanations":{"B":"This keeps the original water amount instead of scaling it.","C":"This repeats the juice amount as water.","D":"This multiplies the water by the juice amount rather than by the scale factor."}}', 'The juice amount doubles from 6 to 12. Water must also double: 3 × 2 = 6 cups.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.WHOLE.MASTERY-CHALLENGE.7', 'G9-T1-WHOLE-MASTERY-CHALLENGE', 7, 'G9-NUM-RATIO-RATE', 'A cyclist travels 60 km in 4 hours at a constant speed. What is the unit rate?', '{"type":"multiple_choice","options":{"A":"64 km/h","B":"56 km/h","C":"240 km/h","D":"15 km/h"},"correct_option":"D","distractor_explanations":{"A":"This adds distance and time instead of dividing.","B":"This subtracts rather than finding a unit rate.","C":"This multiplies distance by time instead of dividing."}}', 'Speed = distance ÷ time = 60 ÷ 4 = 15 km/h.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.WHOLE.MASTERY-CHALLENGE.8', 'G9-T1-WHOLE-MASTERY-CHALLENGE', 8, 'G9-NUM-DIRECT-INVERSE-PROPORTION', 'Five identical notebooks cost R55. At the same price per notebook, what do eight notebooks cost?', '{"type":"multiple_choice","options":{"A":"R440","B":"R11","C":"R88","D":"R63"},"correct_option":"C","distractor_explanations":{"A":"This multiplies the total for five notebooks by eight.","B":"This is the unit price, not the price of eight notebooks.","D":"This adds the number of notebooks to the price."}}', 'One notebook costs R55 ÷ 5 = R11. Eight cost 8 × R11 = R88.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.WHOLE.MASTERY-CHALLENGE.9', 'G9-T1-WHOLE-MASTERY-CHALLENGE', 9, 'G9-NUM-DIRECT-INVERSE-PROPORTION', 'Four workers complete a job in 12 days at the same rate. How many days would eight workers take?', '{"type":"multiple_choice","options":{"A":"48 days","B":"6 days","C":"24 days","D":"12 days"},"correct_option":"B","distractor_explanations":{"A":"This gives worker-days rather than days for eight workers.","C":"This treats days as directly proportional to workers.","D":"This ignores the increase in workers."}}', 'The job needs 4 × 12 = 48 worker-days. With 8 workers: 48 ÷ 8 = 6 days.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.WHOLE.MASTERY-CHALLENGE.10', 'G9-T1-WHOLE-MASTERY-CHALLENGE', 10, 'G9-NUM-FINANCIAL-APPLICATIONS', 'A salesperson earns 6% commission on sales of R2000. What is the commission?', '{"type":"multiple_choice","options":{"A":"R1200","B":"R2006","C":"R12","D":"R120"},"correct_option":"D","distractor_explanations":{"A":"This uses 60% instead of 6%.","B":"This adds 6 rand instead of taking 6%.","C":"This uses 0.6% instead of 6%."}}', '6% = 0.06. Commission = 0.06 × R2000 = R120.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.WHOLE.MASTERY-CHALLENGE.11', 'G9-T1-WHOLE-MASTERY-CHALLENGE', 11, 'G9-NUM-FINANCIAL-APPLICATIONS', 'A bicycle rental costs R55 per day plus a once-off R40 deposit. What is paid at collection for 3 days?', '{"type":"multiple_choice","options":{"A":"R285","B":"R95","C":"R205","D":"R165"},"correct_option":"C","distractor_explanations":{"A":"This charges the once-off deposit three times.","B":"This includes only one rental day.","D":"This omits the once-off deposit."}}', 'Rental = 3 × R55 = R165. Add one deposit of R40: R205.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.WHOLE.MASTERY-CHALLENGE.12', 'G9-T1-WHOLE-MASTERY-CHALLENGE', 12, 'G9-NUM-FINANCIAL-APPLICATIONS', 'R1400 is invested at 10% compound interest per year. What is the balance after two years?', '{"type":"multiple_choice","options":{"A":"R1704.00","B":"R1694.00","C":"R1680.00","D":"R1540.00"},"correct_option":"B","distractor_explanations":{"A":"This adds an extra R10 after compounding.","C":"This adds simple interest for two years.","D":"This stops after one year."}}', 'After year 1: R1400 × 1.10 = R1540.00. After year 2: R1540.00 × 1.10 = R1694.00.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.WHOLE.MASTERY-CHALLENGE.13', 'G9-T1-WHOLE-MASTERY-CHALLENGE', 13, 'G9-NUM-WHOLE-HCF-LCM', 'A learner says the HCF of 30 and 36 is their product. Which correction is valid?', '{"type":"multiple_choice","options":{"A":"HCF means the greatest number that divides both; 6 divides both 30 and 36.","B":"HCF means multiply the two numbers and then choose a factor.","C":"HCF is always the smaller of the two numbers.","D":"HCF means the least common multiple of the two numbers."},"correct_option":"A","distractor_explanations":{"B":"The product is not the definition of HCF.","C":"The smaller number need not divide the larger one.","D":"LCM and HCF are different concepts."}}', '30 = 6 × 5 and 36 = 6 × 6. The common greatest factor is 6.', 2, 'mathematical_reasoning', 'complex', 'verbal'),
  ('Q.G9.T1C.WHOLE.MASTERY-CHALLENGE.14', 'G9-T1-WHOLE-MASTERY-CHALLENGE', 14, 'G9-NUM-RATIO-RATE', 'Map set 3 has scale 1 cm : 7 km. Which calculation models 9.5 cm on the map?', '{"type":"multiple_choice","options":{"A":"9.5 ÷ 7 km","B":"9.5 + 7 km","C":"9.5 km","D":"9.5 × 7 = 66.5 km"},"correct_option":"D","distractor_explanations":{"A":"Dividing reverses the scale relationship.","B":"A scale is multiplicative, not additive.","C":"This ignores that 1 cm represents 7 km."}}', 'Each centimetre represents 7 km. Therefore 9.5 cm represents 9.5 × 7 = 66.5 km.', 2, 'mathematical_reasoning', 'complex', 'verbal'),
  ('Q.G9.T1C.WHOLE.MASTERY-CHALLENGE.15', 'G9-T1-WHOLE-MASTERY-CHALLENGE', 15, 'G9-NUM-FINANCIAL-APPLICATIONS', 'Why is compound interest on R1200 at 9% for two years greater than simple interest at the same rate?', '{"type":"multiple_choice","options":{"A":"Interest is subtracted in the first year and added in the second.","B":"The principal is divided by the rate each year.","C":"The second year’s interest is calculated on R1308.00, not on R1200.","D":"The percentage becomes 18% in the second year."},"correct_option":"C","distractor_explanations":{"A":"Both years add interest for a positive investment.","B":"The rate is applied to the growing balance.","D":"The annual rate remains unchanged."}}', 'After year 1 the balance is R1200 × 1.09 = R1308.00. Year 2 interest is calculated from that balance.', 2, 'mathematical_reasoning', 'complex', 'verbal'),
  ('Q.G9.T1C.WHOLE.MASTERY-CHALLENGE.16', 'G9-T1-WHOLE-MASTERY-CHALLENGE', 16, 'G9-NUM-DIRECT-INVERSE-PROPORTION', 'Which situation in set 3 is inverse proportion?', '{"type":"multiple_choice","options":{"A":"A taxi fare rises when more kilometres are travelled at a fixed rate.","B":"For a fixed amount of concrete, more equal-rate mixers finish in fewer hours.","C":"At a fixed unit price, buying more pens increases the total cost.","D":"A recipe doubles every ingredient when the number of portions doubles."},"correct_option":"B","distractor_explanations":{"A":"Distance and fare increase together, so this is direct proportion.","C":"Both quantities increase together, so this is direct proportion.","D":"Both quantities increase together, so this is direct proportion."}}', 'For a fixed total task, rate × time is constant. Increasing the rate or workers therefore decreases the time.', 2, 'mathematical_reasoning', 'complex', 'verbal'),
  ('Q.G9.T1C.WHOLE.ENDLINE-REASSESSMENT-B.1', 'G9-T1-WHOLE-MASTERY-ENDLINE-REASSESSMENT-B', 1, 'G9-NUM-REAL-IRRATIONAL', 'Which statement correctly classifies √100?', '{"type":"multiple_choice","options":{"A":"10 is a natural number, an integer and a rational number.","B":"It is irrational because it is written with a root sign.","C":"It is not real because square roots are not numbers.","D":"It is the negative integer −10."},"correct_option":"A","distractor_explanations":{"B":"The radicand is a perfect square, so its square root is an integer.","C":"The square root of a positive number is real.","D":"√ denotes the principal, non-negative square root."}}', '√100 = 10. Every natural number is also an integer and rational.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.WHOLE.ENDLINE-REASSESSMENT-B.2', 'G9-T1-WHOLE-MASTERY-ENDLINE-REASSESSMENT-B', 2, 'G9-NUM-REAL-IRRATIONAL', 'Which number is irrational in this number set 4?', '{"type":"multiple_choice","options":{"A":"√100","B":"0.125","C":"−3/8","D":"√20"},"correct_option":"D","distractor_explanations":{"A":"√100 is an integer and is therefore rational.","B":"A terminating decimal is rational.","C":"A ratio of integers with a non-zero denominator is rational."}}', '20 is not a perfect square, so √20 cannot be written as a ratio of integers. The other three numbers are rational.', 2, 'mathematical_reasoning', 'complex', 'verbal'),
  ('Q.G9.T1C.WHOLE.ENDLINE-REASSESSMENT-B.3', 'G9-T1-WHOLE-MASTERY-ENDLINE-REASSESSMENT-B', 3, 'G9-NUM-WHOLE-HCF-LCM', 'What is the prime factorisation of 480?', '{"type":"multiple_choice","options":{"A":"2^5 × 3² × 5","B":"2^6 × 3 × 5","C":"2^5 × 3 × 5","D":"2^4 × 3 × 5"},"correct_option":"C","distractor_explanations":{"A":"This introduces an extra factor of 3.","B":"This introduces an extra factor of 2.","D":"This omits one factor of 2."}}', '480 = 32 × 15 = 2^5 × 3 × 5.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.WHOLE.ENDLINE-REASSESSMENT-B.4', 'G9-T1-WHOLE-MASTERY-ENDLINE-REASSESSMENT-B', 4, 'G9-NUM-WHOLE-HCF-LCM', 'Determine the HCF of 30 and 45.', '{"type":"multiple_choice","options":{"A":"45","B":"15","C":"5","D":"30"},"correct_option":"B","distractor_explanations":{"A":"This is one of the numbers, not a factor of 30.","C":"This is common, but not the highest common factor.","D":"This is one of the numbers, not a factor of 45."}}', '30 = 2 × 3 × 5 and 45 = 3² × 5. The common factors give 3 × 5 = 15.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.WHOLE.ENDLINE-REASSESSMENT-B.5', 'G9-T1-WHOLE-MASTERY-ENDLINE-REASSESSMENT-B', 5, 'G9-NUM-WHOLE-HCF-LCM', 'Two bells ring every 20 and 30 minutes. After how many minutes will they next ring together?', '{"type":"multiple_choice","options":{"A":"60","B":"10","C":"50","D":"120"},"correct_option":"A","distractor_explanations":{"B":"This is the HCF, not the first common multiple.","C":"This is not divisible by both intervals.","D":"This doubles the LCM unnecessarily."}}', 'LCM(20, 30) = LCM(2² × 5, 2 × 3 × 5) = 2² × 3 × 5 = 60.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.WHOLE.ENDLINE-REASSESSMENT-B.6', 'G9-T1-WHOLE-MASTERY-ENDLINE-REASSESSMENT-B', 6, 'G9-NUM-RATIO-RATE', 'A fruit drink uses 7:3 cups of juice to water. How many cups of water are needed for 14 cups of juice?', '{"type":"multiple_choice","options":{"A":"3","B":"14","C":"21","D":"6"},"correct_option":"D","distractor_explanations":{"A":"This keeps the original water amount instead of scaling it.","B":"This repeats the juice amount as water.","C":"This multiplies the water by the juice amount rather than by the scale factor."}}', 'The juice amount doubles from 7 to 14. Water must also double: 3 × 2 = 6 cups.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.WHOLE.ENDLINE-REASSESSMENT-B.7', 'G9-T1-WHOLE-MASTERY-ENDLINE-REASSESSMENT-B', 7, 'G9-NUM-RATIO-RATE', 'A cyclist travels 75 km in 5 hours at a constant speed. What is the unit rate?', '{"type":"multiple_choice","options":{"A":"70 km/h","B":"375 km/h","C":"15 km/h","D":"80 km/h"},"correct_option":"C","distractor_explanations":{"A":"This subtracts rather than finding a unit rate.","B":"This multiplies distance by time instead of dividing.","D":"This adds distance and time instead of dividing."}}', 'Speed = distance ÷ time = 75 ÷ 5 = 15 km/h.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.WHOLE.ENDLINE-REASSESSMENT-B.8', 'G9-T1-WHOLE-MASTERY-ENDLINE-REASSESSMENT-B', 8, 'G9-NUM-DIRECT-INVERSE-PROPORTION', 'Five identical notebooks cost R60. At the same price per notebook, what do eight notebooks cost?', '{"type":"multiple_choice","options":{"A":"R12","B":"R96","C":"R68","D":"R480"},"correct_option":"B","distractor_explanations":{"A":"This is the unit price, not the price of eight notebooks.","C":"This adds the number of notebooks to the price.","D":"This multiplies the total for five notebooks by eight."}}', 'One notebook costs R60 ÷ 5 = R12. Eight cost 8 × R12 = R96.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.WHOLE.ENDLINE-REASSESSMENT-B.9', 'G9-T1-WHOLE-MASTERY-ENDLINE-REASSESSMENT-B', 9, 'G9-NUM-DIRECT-INVERSE-PROPORTION', 'Four workers complete a job in 15 days at the same rate. How many days would eight workers take?', '{"type":"multiple_choice","options":{"A":"7.5 days","B":"30 days","C":"15 days","D":"60 days"},"correct_option":"A","distractor_explanations":{"B":"This treats days as directly proportional to workers.","C":"This ignores the increase in workers.","D":"This gives worker-days rather than days for eight workers."}}', 'The job needs 4 × 15 = 60 worker-days. With 8 workers: 60 ÷ 8 = 7.5 days.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.WHOLE.ENDLINE-REASSESSMENT-B.10', 'G9-T1-WHOLE-MASTERY-ENDLINE-REASSESSMENT-B', 10, 'G9-NUM-FINANCIAL-APPLICATIONS', 'A salesperson earns 6% commission on sales of R2500. What is the commission?', '{"type":"multiple_choice","options":{"A":"R150","B":"R1500","C":"R2506","D":"R15"},"correct_option":"A","distractor_explanations":{"B":"This uses 60% instead of 6%.","C":"This adds 6 rand instead of taking 6%.","D":"This uses 0.6% instead of 6%."}}', '6% = 0.06. Commission = 0.06 × R2500 = R150.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.WHOLE.ENDLINE-REASSESSMENT-B.11', 'G9-T1-WHOLE-MASTERY-ENDLINE-REASSESSMENT-B', 11, 'G9-NUM-FINANCIAL-APPLICATIONS', 'A bicycle rental costs R60 per day plus a once-off R50 deposit. What is paid at collection for 3 days?', '{"type":"multiple_choice","options":{"A":"R180","B":"R330","C":"R110","D":"R230"},"correct_option":"D","distractor_explanations":{"A":"This omits the once-off deposit.","B":"This charges the once-off deposit three times.","C":"This includes only one rental day."}}', 'Rental = 3 × R60 = R180. Add one deposit of R50: R230.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.WHOLE.ENDLINE-REASSESSMENT-B.12', 'G9-T1-WHOLE-MASTERY-ENDLINE-REASSESSMENT-B', 12, 'G9-NUM-FINANCIAL-APPLICATIONS', 'R1500 is invested at 10% compound interest per year. What is the balance after two years?', '{"type":"multiple_choice","options":{"A":"R1650.00","B":"R1825.00","C":"R1815.00","D":"R1800.00"},"correct_option":"C","distractor_explanations":{"A":"This stops after one year.","B":"This adds an extra R10 after compounding.","D":"This adds simple interest for two years."}}', 'After year 1: R1500 × 1.10 = R1650.00. After year 2: R1650.00 × 1.10 = R1815.00.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.WHOLE.ENDLINE-REASSESSMENT-B.13', 'G9-T1-WHOLE-MASTERY-ENDLINE-REASSESSMENT-B', 13, 'G9-NUM-WHOLE-HCF-LCM', 'A learner says the HCF of 36 and 42 is their product. Which correction is valid?', '{"type":"multiple_choice","options":{"A":"HCF means the least common multiple of the two numbers.","B":"HCF means the greatest number that divides both; 6 divides both 36 and 42.","C":"HCF means multiply the two numbers and then choose a factor.","D":"HCF is always the smaller of the two numbers."},"correct_option":"B","distractor_explanations":{"A":"LCM and HCF are different concepts.","C":"The product is not the definition of HCF.","D":"The smaller number need not divide the larger one."}}', '36 = 6 × 6 and 42 = 6 × 7. The common greatest factor is 6.', 2, 'mathematical_reasoning', 'complex', 'verbal'),
  ('Q.G9.T1C.WHOLE.ENDLINE-REASSESSMENT-B.14', 'G9-T1-WHOLE-MASTERY-ENDLINE-REASSESSMENT-B', 14, 'G9-NUM-RATIO-RATE', 'Map set 4 has scale 1 cm : 8 km. Which calculation models 10.5 cm on the map?', '{"type":"multiple_choice","options":{"A":"10.5 × 8 = 84 km","B":"10.5 ÷ 8 km","C":"10.5 + 8 km","D":"10.5 km"},"correct_option":"A","distractor_explanations":{"B":"Dividing reverses the scale relationship.","C":"A scale is multiplicative, not additive.","D":"This ignores that 1 cm represents 8 km."}}', 'Each centimetre represents 8 km. Therefore 10.5 cm represents 10.5 × 8 = 84 km.', 2, 'mathematical_reasoning', 'complex', 'verbal'),
  ('Q.G9.T1C.WHOLE.ENDLINE-REASSESSMENT-B.15', 'G9-T1-WHOLE-MASTERY-ENDLINE-REASSESSMENT-B', 15, 'G9-NUM-FINANCIAL-APPLICATIONS', 'Why is compound interest on R1300 at 10% for two years greater than simple interest at the same rate?', '{"type":"multiple_choice","options":{"A":"The percentage becomes 20% in the second year.","B":"Interest is subtracted in the first year and added in the second.","C":"The principal is divided by the rate each year.","D":"The second year’s interest is calculated on R1430.00, not on R1300."},"correct_option":"D","distractor_explanations":{"A":"The annual rate remains unchanged.","B":"Both years add interest for a positive investment.","C":"The rate is applied to the growing balance."}}', 'After year 1 the balance is R1300 × 1.10 = R1430.00. Year 2 interest is calculated from that balance.', 2, 'mathematical_reasoning', 'complex', 'verbal'),
  ('Q.G9.T1C.WHOLE.ENDLINE-REASSESSMENT-B.16', 'G9-T1-WHOLE-MASTERY-ENDLINE-REASSESSMENT-B', 16, 'G9-NUM-DIRECT-INVERSE-PROPORTION', 'Which situation in set 4 is inverse proportion?', '{"type":"multiple_choice","options":{"A":"A recipe doubles every ingredient when the number of portions doubles.","B":"A taxi fare rises when more kilometres are travelled at a fixed rate.","C":"For a fixed data file, a higher download rate needs less time.","D":"At a fixed unit price, buying more pens increases the total cost."},"correct_option":"C","distractor_explanations":{"A":"Both quantities increase together, so this is direct proportion.","B":"Distance and fare increase together, so this is direct proportion.","D":"Both quantities increase together, so this is direct proportion."}}', 'For a fixed total task, rate × time is constant. Increasing the rate or workers therefore decreases the time.', 2, 'mathematical_reasoning', 'complex', 'verbal'),
  ('Q.G9.T1C.ENTRY.WHOLE.1', 'G9-T1-ENTRY-BASELINE-A', 1, 'G9-NUM-WHOLE-HCF-LCM', 'Determine the HCF of 36 and 54.', '{"type":"multiple_choice","options":{"A":"18","B":"6","C":"36","D":"54"},"correct_option":"A","distractor_explanations":{"B":"This is common, but not the highest common factor.","C":"This is one of the numbers, not a factor of 54.","D":"This is one of the numbers, not a factor of 36."}}', '36 = 2 × 3 × 6 and 54 = 3² × 6. The common factors give 3 × 6 = 18.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.ENTRY.WHOLE.2', 'G9-T1-ENTRY-BASELINE-A', 2, 'G9-NUM-WHOLE-HCF-LCM', 'Two bells ring every 24 and 36 minutes. After how many minutes will they next ring together?', '{"type":"multiple_choice","options":{"A":"12","B":"60","C":"144","D":"72"},"correct_option":"D","distractor_explanations":{"A":"This is the HCF, not the first common multiple.","B":"This is not divisible by both intervals.","C":"This doubles the LCM unnecessarily."}}', 'LCM(24, 36) = LCM(2² × 6, 2 × 3 × 6) = 2² × 3 × 6 = 72.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.ENTRY.WHOLE.3', 'G9-T1-ENTRY-BASELINE-A', 3, 'G9-NUM-RATIO-RATE', 'A fruit drink uses 8:3 cups of juice to water. How many cups of water are needed for 16 cups of juice?', '{"type":"multiple_choice","options":{"A":"16","B":"24","C":"6","D":"3"},"correct_option":"C","distractor_explanations":{"A":"This repeats the juice amount as water.","B":"This multiplies the water by the juice amount rather than by the scale factor.","D":"This keeps the original water amount instead of scaling it."}}', 'The juice amount doubles from 8 to 16. Water must also double: 3 × 2 = 6 cups.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.INT.TOPIC-BASELINE.1', 'G9-T1-INTEGERS-MASTERY-TOPIC-BASELINE', 1, 'G9-NUM-INTEGERS-OPERATIONS', 'Calculate: −10 + 18.', '{"type":"multiple_choice","options":{"A":"22","B":"8","C":"-22","D":"-8"},"correct_option":"B","distractor_explanations":{"A":"This ignores the negative starting value.","C":"This adds magnitudes with a negative sign.","D":"This reverses the subtraction direction."}}', 'Starting at −10, move 18 units right: −10 + 18 = 8.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.INT.TOPIC-BASELINE.2', 'G9-T1-INTEGERS-MASTERY-TOPIC-BASELINE', 2, 'G9-NUM-INTEGERS-OPERATIONS', 'Calculate: 9 − 17.', '{"type":"multiple_choice","options":{"A":"-8","B":"8","C":"26","D":"-26"},"correct_option":"A","distractor_explanations":{"B":"This reverses the order of subtraction.","C":"This adds the two magnitudes.","D":"This adds magnitudes and keeps a negative sign."}}', '9 − 17 = −(17 − 9) = −8.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.INT.TOPIC-BASELINE.3', 'G9-T1-INTEGERS-MASTERY-TOPIC-BASELINE', 3, 'G9-NUM-INTEGERS-OPERATIONS', 'Calculate: (−5) × (−8).', '{"type":"multiple_choice","options":{"A":"-40","B":"13","C":"-13","D":"40"},"correct_option":"D","distractor_explanations":{"A":"Two negative factors give a positive product.","B":"This adds instead of multiplying.","C":"This adds and keeps an incorrect negative sign."}}', 'Two negatives multiply to a positive. 5 × 8 = 40.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.INT.TOPIC-BASELINE.4', 'G9-T1-INTEGERS-MASTERY-TOPIC-BASELINE', 4, 'G9-NUM-INTEGERS-OPERATIONS', 'Calculate: (−18) ÷ 3.', '{"type":"multiple_choice","options":{"A":"-15","B":"15","C":"-6","D":"6"},"correct_option":"C","distractor_explanations":{"A":"This subtracts instead of divides.","B":"This subtracts and loses the sign.","D":"The magnitude is correct but the sign is lost."}}', 'A negative divided by a positive is negative: −18 ÷ 3 = −6.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.INT.TOPIC-BASELINE.5', 'G9-T1-INTEGERS-MASTERY-TOPIC-BASELINE', 5, 'G9-NUM-INTEGERS-POWERS-ROOTS', 'Evaluate: −3².', '{"type":"multiple_choice","options":{"A":"6","B":"-9","C":"9","D":"-6"},"correct_option":"B","distractor_explanations":{"A":"This multiplies by 2 and loses the negative.","C":"Without brackets, the exponent is applied before the leading negative.","D":"This multiplies by 2 rather than squaring."}}', 'Exponent first: 3² = 9. The leading negative gives −9.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.INT.TOPIC-BASELINE.6', 'G9-T1-INTEGERS-MASTERY-TOPIC-BASELINE', 6, 'G9-NUM-INTEGERS-POWERS-ROOTS', 'Evaluate: (−3)².', '{"type":"multiple_choice","options":{"A":"9","B":"-9","C":"-6","D":"6"},"correct_option":"A","distractor_explanations":{"B":"The brackets make the negative number the base, so the product is positive.","C":"This doubles rather than squares.","D":"This doubles rather than squares."}}', '(−3)² = (−3) × (−3) = 9.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.INT.TOPIC-BASELINE.7', 'G9-T1-INTEGERS-MASTERY-TOPIC-BASELINE', 7, 'G9-NUM-INTEGERS-POWERS-ROOTS', 'What is the cube root of −64?', '{"type":"multiple_choice","options":{"A":"4","B":"-16","C":"16","D":"-4"},"correct_option":"D","distractor_explanations":{"A":"A positive cube gives a positive result.","B":"This is related to the square, not the cube root.","C":"This is related to the square, not the cube root."}}', '(−4)³ = −64, so the cube root is −4.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.INT.TOPIC-BASELINE.8', 'G9-T1-INTEGERS-MASTERY-TOPIC-BASELINE', 8, 'G9-NUM-INTEGERS-OPERATIONS', 'Calculate: −3 + 6 × (−3).', '{"type":"multiple_choice","options":{"A":"3","B":"21","C":"-21","D":"-27"},"correct_option":"C","distractor_explanations":{"A":"This loses the negative product.","B":"This loses both negative signs.","D":"This adds before multiplying."}}', 'Multiply first: 6 × (−3) = −18. Then −3 + (−18) = −21.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.INT.TOPIC-BASELINE.9', 'G9-T1-INTEGERS-MASTERY-TOPIC-BASELINE', 9, 'G9-NUM-INTEGERS-OPERATIONS', 'A learner says two negatives always make a negative. Which multiplication in set 1 disproves this?', '{"type":"multiple_choice","options":{"A":"(−4) + (−5) = −9","B":"(−4) × (−5) = 20","C":"(−4) × 5 = −20","D":"4 × 5 = 20"},"correct_option":"B","distractor_explanations":{"A":"This is addition, not multiplication.","C":"This has only one negative factor.","D":"This has no negative factors."}}', 'The product of two negative factors is positive: (−4) × (−5) = 20.', 3, 'mathematical_reasoning', 'complex', 'verbal'),
  ('Q.G9.T1C.INT.TOPIC-BASELINE.10', 'G9-T1-INTEGERS-MASTERY-TOPIC-BASELINE', 10, 'G9-NUM-INTEGERS-POWERS-ROOTS', 'Which expression in set 1 has value −1?', '{"type":"multiple_choice","options":{"A":"(−3)² ÷ 9","B":"3³ ÷ 27","C":"−3² ÷ −9","D":"(−3)³ ÷ 27"},"correct_option":"D","distractor_explanations":{"A":"This equals 1 because the square is positive.","B":"This equals 1 because both quantities are positive.","C":"This equals 1 because both negatives cancel."}}', '(−3)³ = −27. Then −27 ÷ 27 = −1.', 3, 'mathematical_reasoning', 'complex', 'verbal'),
  ('Q.G9.T1C.INT.TOPIC-BASELINE.11', 'G9-T1-INTEGERS-MASTERY-TOPIC-BASELINE', 11, 'G9-NUM-INTEGERS-OPERATIONS', 'A temperature changes from −7°C to 5°C. What is the increase?', '{"type":"multiple_choice","options":{"A":"-12°C","B":"5°C","C":"12°C","D":"2°C"},"correct_option":"C","distractor_explanations":{"A":"This gives the change in the wrong direction.","B":"This gives the final temperature, not the increase.","D":"This subtracts only the displayed positive parts."}}', 'Increase = final − initial = 5 − (−7) = 12°C.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.INT.TOPIC-BASELINE.12', 'G9-T1-INTEGERS-MASTERY-TOPIC-BASELINE', 12, 'G9-NUM-INTEGERS-POWERS-ROOTS', 'Which statement is always true for an integer t in set 1?', '{"type":"multiple_choice","options":{"A":"t³ is always positive.","B":"t² is greater than or equal to 0.","C":"t² is always greater than 0.","D":"−t is always negative."},"correct_option":"B","distractor_explanations":{"A":"A negative integer has a negative cube.","C":"When t = 0, t² = 0, not greater than 0.","D":"If t is negative, −t is positive."}}', 'Squaring an integer multiplies it by itself. The product is non-negative; it is zero only when t = 0.', 3, 'mathematical_reasoning', 'complex', 'verbal'),
  ('Q.G9.T1C.INT.ENDLINE.1', 'G9-T1-INTEGERS-MASTERY-ENDLINE', 1, 'G9-NUM-INTEGERS-OPERATIONS', 'Calculate: −11 + 19.', '{"type":"multiple_choice","options":{"A":"-22","B":"-8","C":"22","D":"8"},"correct_option":"D","distractor_explanations":{"A":"This adds magnitudes with a negative sign.","B":"This reverses the subtraction direction.","C":"This ignores the negative starting value."}}', 'Starting at −11, move 19 units right: −11 + 19 = 8.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.INT.ENDLINE.2', 'G9-T1-INTEGERS-MASTERY-ENDLINE', 2, 'G9-NUM-INTEGERS-OPERATIONS', 'Calculate: 10 − 18.', '{"type":"multiple_choice","options":{"A":"28","B":"-28","C":"-8","D":"8"},"correct_option":"C","distractor_explanations":{"A":"This adds the two magnitudes.","B":"This adds magnitudes and keeps a negative sign.","D":"This reverses the order of subtraction."}}', '10 − 18 = −(18 − 10) = −8.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.INT.ENDLINE.3', 'G9-T1-INTEGERS-MASTERY-ENDLINE', 3, 'G9-NUM-INTEGERS-OPERATIONS', 'Calculate: (−6) × (−9).', '{"type":"multiple_choice","options":{"A":"-15","B":"54","C":"-54","D":"15"},"correct_option":"B","distractor_explanations":{"A":"This adds and keeps an incorrect negative sign.","C":"Two negative factors give a positive product.","D":"This adds instead of multiplying."}}', 'Two negatives multiply to a positive. 6 × 9 = 54.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.INT.ENDLINE.4', 'G9-T1-INTEGERS-MASTERY-ENDLINE', 4, 'G9-NUM-INTEGERS-OPERATIONS', 'Calculate: (−24) ÷ 4.', '{"type":"multiple_choice","options":{"A":"-6","B":"6","C":"-20","D":"20"},"correct_option":"A","distractor_explanations":{"B":"The magnitude is correct but the sign is lost.","C":"This subtracts instead of divides.","D":"This subtracts and loses the sign."}}', 'A negative divided by a positive is negative: −24 ÷ 4 = −6.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.INT.ENDLINE.5', 'G9-T1-INTEGERS-MASTERY-ENDLINE', 5, 'G9-NUM-INTEGERS-POWERS-ROOTS', 'Evaluate: −4².', '{"type":"multiple_choice","options":{"A":"16","B":"-8","C":"8","D":"-16"},"correct_option":"D","distractor_explanations":{"A":"Without brackets, the exponent is applied before the leading negative.","B":"This multiplies by 2 rather than squaring.","C":"This multiplies by 2 and loses the negative."}}', 'Exponent first: 4² = 16. The leading negative gives −16.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.INT.ENDLINE.6', 'G9-T1-INTEGERS-MASTERY-ENDLINE', 6, 'G9-NUM-INTEGERS-POWERS-ROOTS', 'Evaluate: (−4)².', '{"type":"multiple_choice","options":{"A":"-8","B":"8","C":"16","D":"-16"},"correct_option":"C","distractor_explanations":{"A":"This doubles rather than squares.","B":"This doubles rather than squares.","D":"The brackets make the negative number the base, so the product is positive."}}', '(−4)² = (−4) × (−4) = 16.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.INT.ENDLINE.7', 'G9-T1-INTEGERS-MASTERY-ENDLINE', 7, 'G9-NUM-INTEGERS-POWERS-ROOTS', 'What is the cube root of −125?', '{"type":"multiple_choice","options":{"A":"25","B":"-5","C":"5","D":"-25"},"correct_option":"B","distractor_explanations":{"A":"This is related to the square, not the cube root.","C":"A positive cube gives a positive result.","D":"This is related to the square, not the cube root."}}', '(−5)³ = −125, so the cube root is −5.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.INT.ENDLINE.8', 'G9-T1-INTEGERS-MASTERY-ENDLINE', 8, 'G9-NUM-INTEGERS-OPERATIONS', 'Calculate: −4 + 8 × (−3).', '{"type":"multiple_choice","options":{"A":"-28","B":"-36","C":"4","D":"28"},"correct_option":"A","distractor_explanations":{"B":"This adds before multiplying.","C":"This loses the negative product.","D":"This loses both negative signs."}}', 'Multiply first: 8 × (−3) = −24. Then −4 + (−24) = −28.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.INT.ENDLINE.9', 'G9-T1-INTEGERS-MASTERY-ENDLINE', 9, 'G9-NUM-INTEGERS-OPERATIONS', 'A learner says two negatives always make a negative. Which multiplication in set 2 disproves this?', '{"type":"multiple_choice","options":{"A":"(−5) × 6 = −30","B":"5 × 6 = 30","C":"(−5) + (−6) = −11","D":"(−5) × (−6) = 30"},"correct_option":"D","distractor_explanations":{"A":"This has only one negative factor.","B":"This has no negative factors.","C":"This is addition, not multiplication."}}', 'The product of two negative factors is positive: (−5) × (−6) = 30.', 3, 'mathematical_reasoning', 'complex', 'verbal'),
  ('Q.G9.T1C.INT.ENDLINE.10', 'G9-T1-INTEGERS-MASTERY-ENDLINE', 10, 'G9-NUM-INTEGERS-POWERS-ROOTS', 'Which expression in set 2 has value −1?', '{"type":"multiple_choice","options":{"A":"−4² ÷ −16","B":"(−4)³ ÷ 64","C":"(−4)² ÷ 16","D":"4³ ÷ 64"},"correct_option":"B","distractor_explanations":{"A":"This equals 1 because both negatives cancel.","C":"This equals 1 because the square is positive.","D":"This equals 1 because both quantities are positive."}}', '(−4)³ = −64. Then −64 ÷ 64 = −1.', 3, 'mathematical_reasoning', 'complex', 'verbal'),
  ('Q.G9.T1C.INT.ENDLINE.11', 'G9-T1-INTEGERS-MASTERY-ENDLINE', 11, 'G9-NUM-INTEGERS-OPERATIONS', 'A temperature changes from −8°C to 6°C. What is the increase?', '{"type":"multiple_choice","options":{"A":"14°C","B":"2°C","C":"-14°C","D":"6°C"},"correct_option":"A","distractor_explanations":{"B":"This subtracts only the displayed positive parts.","C":"This gives the change in the wrong direction.","D":"This gives the final temperature, not the increase."}}', 'Increase = final − initial = 6 − (−8) = 14°C.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.INT.ENDLINE.12', 'G9-T1-INTEGERS-MASTERY-ENDLINE', 12, 'G9-NUM-INTEGERS-POWERS-ROOTS', 'Which statement is always true for an integer t in set 2?', '{"type":"multiple_choice","options":{"A":"t² is always greater than 0.","B":"−t is always negative.","C":"t³ is always positive.","D":"t² is greater than or equal to 0."},"correct_option":"D","distractor_explanations":{"A":"When t = 0, t² = 0, not greater than 0.","B":"If t is negative, −t is positive.","C":"A negative integer has a negative cube."}}', 'Squaring an integer multiplies it by itself. The product is non-negative; it is zero only when t = 0.', 3, 'mathematical_reasoning', 'complex', 'verbal'),
  ('Q.G9.T1C.INT.ENDLINE.13', 'G9-T1-INTEGERS-MASTERY-ENDLINE', 13, 'G9-NUM-INTEGERS-OPERATIONS', 'Calculate: [10 − (−6)] ÷ 2.', '{"type":"multiple_choice","options":{"A":"16","B":"-8","C":"8","D":"2"},"correct_option":"C","distractor_explanations":{"A":"This stops before dividing by 2.","B":"This treats subtraction of a negative as subtraction.","D":"This divides only the second term."}}', '10 − (−6) = 16. Dividing by 2 gives 8.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.INT.ENDLINE.14', 'G9-T1-INTEGERS-MASTERY-ENDLINE', 14, 'G9-NUM-INTEGERS-POWERS-ROOTS', 'Which number has square root 8?', '{"type":"multiple_choice","options":{"A":"8","B":"64","C":"16","D":"-64"},"correct_option":"B","distractor_explanations":{"A":"This is the root, not the number.","C":"This doubles instead of squaring.","D":"A positive square root has a positive radicand."}}', 'If √x = 8, then x = (8)² = 64.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.INT.ENDLINE.15', 'G9-T1-INTEGERS-MASTERY-ENDLINE', 15, 'G9-NUM-INTEGERS-POWERS-ROOTS', 'Why are brackets important in (−6)²?', '{"type":"multiple_choice","options":{"A":"They make −6 the base that is multiplied by itself.","B":"They make the exponent negative.","C":"They change squaring into multiplication by 2.","D":"They make every answer negative."},"correct_option":"A","distractor_explanations":{"B":"The exponent remains positive 2.","C":"Squaring means multiplying the base by itself.","D":"The square of −6 is positive."}}', '(−6)² = (−6) × (−6) = 36. Without brackets, −6² means −((6)²).', 3, 'mathematical_reasoning', 'complex', 'verbal'),
  ('Q.G9.T1C.INT.ENDLINE.16', 'G9-T1-INTEGERS-MASTERY-ENDLINE', 16, 'G9-NUM-INTEGERS-OPERATIONS', 'Calculate: |−12| − |5|.', '{"type":"multiple_choice","options":{"A":"-7","B":"17","C":"9","D":"7"},"correct_option":"D","distractor_explanations":{"A":"This reverses the subtraction.","B":"This adds absolute values.","C":"This changes the second absolute value incorrectly."}}', '|−12| = 12 and |5| = 5; 12 − 5 = 7.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.INT.MASTERY-CHALLENGE.1', 'G9-T1-INTEGERS-MASTERY-CHALLENGE', 1, 'G9-NUM-INTEGERS-OPERATIONS', 'Calculate: −12 + 20.', '{"type":"multiple_choice","options":{"A":"22","B":"8","C":"-22","D":"-8"},"correct_option":"B","distractor_explanations":{"A":"This ignores the negative starting value.","C":"This adds magnitudes with a negative sign.","D":"This reverses the subtraction direction."}}', 'Starting at −12, move 20 units right: −12 + 20 = 8.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.INT.MASTERY-CHALLENGE.2', 'G9-T1-INTEGERS-MASTERY-CHALLENGE', 2, 'G9-NUM-INTEGERS-OPERATIONS', 'Calculate: 11 − 19.', '{"type":"multiple_choice","options":{"A":"-8","B":"8","C":"30","D":"-30"},"correct_option":"A","distractor_explanations":{"B":"This reverses the order of subtraction.","C":"This adds the two magnitudes.","D":"This adds magnitudes and keeps a negative sign."}}', '11 − 19 = −(19 − 11) = −8.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.INT.MASTERY-CHALLENGE.3', 'G9-T1-INTEGERS-MASTERY-CHALLENGE', 3, 'G9-NUM-INTEGERS-OPERATIONS', 'Calculate: (−7) × (−10).', '{"type":"multiple_choice","options":{"A":"-70","B":"17","C":"-17","D":"70"},"correct_option":"D","distractor_explanations":{"A":"Two negative factors give a positive product.","B":"This adds instead of multiplying.","C":"This adds and keeps an incorrect negative sign."}}', 'Two negatives multiply to a positive. 7 × 10 = 70.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.INT.MASTERY-CHALLENGE.4', 'G9-T1-INTEGERS-MASTERY-CHALLENGE', 4, 'G9-NUM-INTEGERS-OPERATIONS', 'Calculate: (−30) ÷ 5.', '{"type":"multiple_choice","options":{"A":"-25","B":"25","C":"-6","D":"6"},"correct_option":"C","distractor_explanations":{"A":"This subtracts instead of divides.","B":"This subtracts and loses the sign.","D":"The magnitude is correct but the sign is lost."}}', 'A negative divided by a positive is negative: −30 ÷ 5 = −6.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.INT.MASTERY-CHALLENGE.5', 'G9-T1-INTEGERS-MASTERY-CHALLENGE', 5, 'G9-NUM-INTEGERS-POWERS-ROOTS', 'Evaluate: −5².', '{"type":"multiple_choice","options":{"A":"10","B":"-25","C":"25","D":"-10"},"correct_option":"B","distractor_explanations":{"A":"This multiplies by 2 and loses the negative.","C":"Without brackets, the exponent is applied before the leading negative.","D":"This multiplies by 2 rather than squaring."}}', 'Exponent first: 5² = 25. The leading negative gives −25.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.INT.MASTERY-CHALLENGE.6', 'G9-T1-INTEGERS-MASTERY-CHALLENGE', 6, 'G9-NUM-INTEGERS-POWERS-ROOTS', 'Evaluate: (−5)².', '{"type":"multiple_choice","options":{"A":"25","B":"-25","C":"-10","D":"10"},"correct_option":"A","distractor_explanations":{"B":"The brackets make the negative number the base, so the product is positive.","C":"This doubles rather than squares.","D":"This doubles rather than squares."}}', '(−5)² = (−5) × (−5) = 25.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.INT.MASTERY-CHALLENGE.7', 'G9-T1-INTEGERS-MASTERY-CHALLENGE', 7, 'G9-NUM-INTEGERS-POWERS-ROOTS', 'What is the cube root of −216?', '{"type":"multiple_choice","options":{"A":"6","B":"-36","C":"36","D":"-6"},"correct_option":"D","distractor_explanations":{"A":"A positive cube gives a positive result.","B":"This is related to the square, not the cube root.","C":"This is related to the square, not the cube root."}}', '(−6)³ = −216, so the cube root is −6.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.INT.MASTERY-CHALLENGE.8', 'G9-T1-INTEGERS-MASTERY-CHALLENGE', 8, 'G9-NUM-INTEGERS-OPERATIONS', 'Calculate: −5 + 10 × (−3).', '{"type":"multiple_choice","options":{"A":"5","B":"35","C":"-35","D":"-45"},"correct_option":"C","distractor_explanations":{"A":"This loses the negative product.","B":"This loses both negative signs.","D":"This adds before multiplying."}}', 'Multiply first: 10 × (−3) = −30. Then −5 + (−30) = −35.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.INT.MASTERY-CHALLENGE.9', 'G9-T1-INTEGERS-MASTERY-CHALLENGE', 9, 'G9-NUM-INTEGERS-OPERATIONS', 'A learner says two negatives always make a negative. Which multiplication in set 3 disproves this?', '{"type":"multiple_choice","options":{"A":"(−6) + (−7) = −13","B":"(−6) × (−7) = 42","C":"(−6) × 7 = −42","D":"6 × 7 = 42"},"correct_option":"B","distractor_explanations":{"A":"This is addition, not multiplication.","C":"This has only one negative factor.","D":"This has no negative factors."}}', 'The product of two negative factors is positive: (−6) × (−7) = 42.', 3, 'mathematical_reasoning', 'complex', 'verbal'),
  ('Q.G9.T1C.INT.MASTERY-CHALLENGE.10', 'G9-T1-INTEGERS-MASTERY-CHALLENGE', 10, 'G9-NUM-INTEGERS-POWERS-ROOTS', 'Which expression in set 3 has value −1?', '{"type":"multiple_choice","options":{"A":"(−5)² ÷ 25","B":"5³ ÷ 125","C":"−5² ÷ −25","D":"(−5)³ ÷ 125"},"correct_option":"D","distractor_explanations":{"A":"This equals 1 because the square is positive.","B":"This equals 1 because both quantities are positive.","C":"This equals 1 because both negatives cancel."}}', '(−5)³ = −125. Then −125 ÷ 125 = −1.', 3, 'mathematical_reasoning', 'complex', 'verbal'),
  ('Q.G9.T1C.INT.MASTERY-CHALLENGE.11', 'G9-T1-INTEGERS-MASTERY-CHALLENGE', 11, 'G9-NUM-INTEGERS-OPERATIONS', 'A temperature changes from −9°C to 7°C. What is the increase?', '{"type":"multiple_choice","options":{"A":"-16°C","B":"7°C","C":"16°C","D":"2°C"},"correct_option":"C","distractor_explanations":{"A":"This gives the change in the wrong direction.","B":"This gives the final temperature, not the increase.","D":"This subtracts only the displayed positive parts."}}', 'Increase = final − initial = 7 − (−9) = 16°C.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.INT.MASTERY-CHALLENGE.12', 'G9-T1-INTEGERS-MASTERY-CHALLENGE', 12, 'G9-NUM-INTEGERS-POWERS-ROOTS', 'Which statement is always true for an integer t in set 3?', '{"type":"multiple_choice","options":{"A":"t³ is always positive.","B":"t² is greater than or equal to 0.","C":"t² is always greater than 0.","D":"−t is always negative."},"correct_option":"B","distractor_explanations":{"A":"A negative integer has a negative cube.","C":"When t = 0, t² = 0, not greater than 0.","D":"If t is negative, −t is positive."}}', 'Squaring an integer multiplies it by itself. The product is non-negative; it is zero only when t = 0.', 3, 'mathematical_reasoning', 'complex', 'verbal'),
  ('Q.G9.T1C.INT.MASTERY-CHALLENGE.13', 'G9-T1-INTEGERS-MASTERY-CHALLENGE', 13, 'G9-NUM-INTEGERS-OPERATIONS', 'Calculate: [11 − (−7)] ÷ 2.', '{"type":"multiple_choice","options":{"A":"9","B":"2","C":"18","D":"-9"},"correct_option":"A","distractor_explanations":{"B":"This divides only the second term.","C":"This stops before dividing by 2.","D":"This treats subtraction of a negative as subtraction."}}', '11 − (−7) = 18. Dividing by 2 gives 9.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.INT.MASTERY-CHALLENGE.14', 'G9-T1-INTEGERS-MASTERY-CHALLENGE', 14, 'G9-NUM-INTEGERS-POWERS-ROOTS', 'Which number has square root 9?', '{"type":"multiple_choice","options":{"A":"18","B":"-81","C":"9","D":"81"},"correct_option":"D","distractor_explanations":{"A":"This doubles instead of squaring.","B":"A positive square root has a positive radicand.","C":"This is the root, not the number."}}', 'If √x = 9, then x = (9)² = 81.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.INT.MASTERY-CHALLENGE.15', 'G9-T1-INTEGERS-MASTERY-CHALLENGE', 15, 'G9-NUM-INTEGERS-POWERS-ROOTS', 'Why are brackets important in (−7)²?', '{"type":"multiple_choice","options":{"A":"They change squaring into multiplication by 2.","B":"They make every answer negative.","C":"They make −7 the base that is multiplied by itself.","D":"They make the exponent negative."},"correct_option":"C","distractor_explanations":{"A":"Squaring means multiplying the base by itself.","B":"The square of −7 is positive.","D":"The exponent remains positive 2."}}', '(−7)² = (−7) × (−7) = 49. Without brackets, −7² means −((7)²).', 3, 'mathematical_reasoning', 'complex', 'verbal'),
  ('Q.G9.T1C.INT.MASTERY-CHALLENGE.16', 'G9-T1-INTEGERS-MASTERY-CHALLENGE', 16, 'G9-NUM-INTEGERS-OPERATIONS', 'Calculate: |−15| − |6|.', '{"type":"multiple_choice","options":{"A":"11","B":"9","C":"-9","D":"21"},"correct_option":"B","distractor_explanations":{"A":"This changes the second absolute value incorrectly.","C":"This reverses the subtraction.","D":"This adds absolute values."}}', '|−15| = 15 and |6| = 6; 15 − 6 = 9.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.INT.ENDLINE-REASSESSMENT-B.1', 'G9-T1-INTEGERS-MASTERY-ENDLINE-REASSESSMENT-B', 1, 'G9-NUM-INTEGERS-OPERATIONS', 'Calculate: −13 + 21.', '{"type":"multiple_choice","options":{"A":"8","B":"-22","C":"-8","D":"22"},"correct_option":"A","distractor_explanations":{"B":"This adds magnitudes with a negative sign.","C":"This reverses the subtraction direction.","D":"This ignores the negative starting value."}}', 'Starting at −13, move 21 units right: −13 + 21 = 8.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.INT.ENDLINE-REASSESSMENT-B.2', 'G9-T1-INTEGERS-MASTERY-ENDLINE-REASSESSMENT-B', 2, 'G9-NUM-INTEGERS-OPERATIONS', 'Calculate: 12 − 20.', '{"type":"multiple_choice","options":{"A":"8","B":"32","C":"-32","D":"-8"},"correct_option":"D","distractor_explanations":{"A":"This reverses the order of subtraction.","B":"This adds the two magnitudes.","C":"This adds magnitudes and keeps a negative sign."}}', '12 − 20 = −(20 − 12) = −8.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.INT.ENDLINE-REASSESSMENT-B.3', 'G9-T1-INTEGERS-MASTERY-ENDLINE-REASSESSMENT-B', 3, 'G9-NUM-INTEGERS-OPERATIONS', 'Calculate: (−8) × (−11).', '{"type":"multiple_choice","options":{"A":"19","B":"-19","C":"88","D":"-88"},"correct_option":"C","distractor_explanations":{"A":"This adds instead of multiplying.","B":"This adds and keeps an incorrect negative sign.","D":"Two negative factors give a positive product."}}', 'Two negatives multiply to a positive. 8 × 11 = 88.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.INT.ENDLINE-REASSESSMENT-B.4', 'G9-T1-INTEGERS-MASTERY-ENDLINE-REASSESSMENT-B', 4, 'G9-NUM-INTEGERS-OPERATIONS', 'Calculate: (−36) ÷ 6.', '{"type":"multiple_choice","options":{"A":"30","B":"-6","C":"6","D":"-30"},"correct_option":"B","distractor_explanations":{"A":"This subtracts and loses the sign.","C":"The magnitude is correct but the sign is lost.","D":"This subtracts instead of divides."}}', 'A negative divided by a positive is negative: −36 ÷ 6 = −6.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.INT.ENDLINE-REASSESSMENT-B.5', 'G9-T1-INTEGERS-MASTERY-ENDLINE-REASSESSMENT-B', 5, 'G9-NUM-INTEGERS-POWERS-ROOTS', 'Evaluate: −6².', '{"type":"multiple_choice","options":{"A":"-36","B":"36","C":"-12","D":"12"},"correct_option":"A","distractor_explanations":{"B":"Without brackets, the exponent is applied before the leading negative.","C":"This multiplies by 2 rather than squaring.","D":"This multiplies by 2 and loses the negative."}}', 'Exponent first: 6² = 36. The leading negative gives −36.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.INT.ENDLINE-REASSESSMENT-B.6', 'G9-T1-INTEGERS-MASTERY-ENDLINE-REASSESSMENT-B', 6, 'G9-NUM-INTEGERS-POWERS-ROOTS', 'Evaluate: (−6)².', '{"type":"multiple_choice","options":{"A":"-36","B":"-12","C":"12","D":"36"},"correct_option":"D","distractor_explanations":{"A":"The brackets make the negative number the base, so the product is positive.","B":"This doubles rather than squares.","C":"This doubles rather than squares."}}', '(−6)² = (−6) × (−6) = 36.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.INT.ENDLINE-REASSESSMENT-B.7', 'G9-T1-INTEGERS-MASTERY-ENDLINE-REASSESSMENT-B', 7, 'G9-NUM-INTEGERS-POWERS-ROOTS', 'What is the cube root of −343?', '{"type":"multiple_choice","options":{"A":"-49","B":"49","C":"-7","D":"7"},"correct_option":"C","distractor_explanations":{"A":"This is related to the square, not the cube root.","B":"This is related to the square, not the cube root.","D":"A positive cube gives a positive result."}}', '(−7)³ = −343, so the cube root is −7.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.INT.ENDLINE-REASSESSMENT-B.8', 'G9-T1-INTEGERS-MASTERY-ENDLINE-REASSESSMENT-B', 8, 'G9-NUM-INTEGERS-OPERATIONS', 'Calculate: −6 + 12 × (−3).', '{"type":"multiple_choice","options":{"A":"42","B":"-42","C":"-54","D":"6"},"correct_option":"B","distractor_explanations":{"A":"This loses both negative signs.","C":"This adds before multiplying.","D":"This loses the negative product."}}', 'Multiply first: 12 × (−3) = −36. Then −6 + (−36) = −42.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.INT.ENDLINE-REASSESSMENT-B.9', 'G9-T1-INTEGERS-MASTERY-ENDLINE-REASSESSMENT-B', 9, 'G9-NUM-INTEGERS-OPERATIONS', 'A learner says two negatives always make a negative. Which multiplication in set 4 disproves this?', '{"type":"multiple_choice","options":{"A":"(−7) × (−8) = 56","B":"(−7) × 8 = −56","C":"7 × 8 = 56","D":"(−7) + (−8) = −15"},"correct_option":"A","distractor_explanations":{"B":"This has only one negative factor.","C":"This has no negative factors.","D":"This is addition, not multiplication."}}', 'The product of two negative factors is positive: (−7) × (−8) = 56.', 3, 'mathematical_reasoning', 'complex', 'verbal'),
  ('Q.G9.T1C.INT.ENDLINE-REASSESSMENT-B.10', 'G9-T1-INTEGERS-MASTERY-ENDLINE-REASSESSMENT-B', 10, 'G9-NUM-INTEGERS-POWERS-ROOTS', 'Which expression in set 4 has value −1?', '{"type":"multiple_choice","options":{"A":"(−6)³ ÷ 216","B":"(−6)² ÷ 36","C":"6³ ÷ 216","D":"−6² ÷ −36"},"correct_option":"A","distractor_explanations":{"B":"This equals 1 because the square is positive.","C":"This equals 1 because both quantities are positive.","D":"This equals 1 because both negatives cancel."}}', '(−6)³ = −216. Then −216 ÷ 216 = −1.', 3, 'mathematical_reasoning', 'complex', 'verbal'),
  ('Q.G9.T1C.INT.ENDLINE-REASSESSMENT-B.11', 'G9-T1-INTEGERS-MASTERY-ENDLINE-REASSESSMENT-B', 11, 'G9-NUM-INTEGERS-OPERATIONS', 'A temperature changes from −10°C to 8°C. What is the increase?', '{"type":"multiple_choice","options":{"A":"2°C","B":"-18°C","C":"8°C","D":"18°C"},"correct_option":"D","distractor_explanations":{"A":"This subtracts only the displayed positive parts.","B":"This gives the change in the wrong direction.","C":"This gives the final temperature, not the increase."}}', 'Increase = final − initial = 8 − (−10) = 18°C.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.INT.ENDLINE-REASSESSMENT-B.12', 'G9-T1-INTEGERS-MASTERY-ENDLINE-REASSESSMENT-B', 12, 'G9-NUM-INTEGERS-POWERS-ROOTS', 'Which statement is always true for an integer t in set 4?', '{"type":"multiple_choice","options":{"A":"−t is always negative.","B":"t³ is always positive.","C":"t² is greater than or equal to 0.","D":"t² is always greater than 0."},"correct_option":"C","distractor_explanations":{"A":"If t is negative, −t is positive.","B":"A negative integer has a negative cube.","D":"When t = 0, t² = 0, not greater than 0."}}', 'Squaring an integer multiplies it by itself. The product is non-negative; it is zero only when t = 0.', 3, 'mathematical_reasoning', 'complex', 'verbal'),
  ('Q.G9.T1C.INT.ENDLINE-REASSESSMENT-B.13', 'G9-T1-INTEGERS-MASTERY-ENDLINE-REASSESSMENT-B', 13, 'G9-NUM-INTEGERS-OPERATIONS', 'Calculate: [12 − (−8)] ÷ 2.', '{"type":"multiple_choice","options":{"A":"-10","B":"10","C":"2","D":"20"},"correct_option":"B","distractor_explanations":{"A":"This treats subtraction of a negative as subtraction.","C":"This divides only the second term.","D":"This stops before dividing by 2."}}', '12 − (−8) = 20. Dividing by 2 gives 10.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.INT.ENDLINE-REASSESSMENT-B.14', 'G9-T1-INTEGERS-MASTERY-ENDLINE-REASSESSMENT-B', 14, 'G9-NUM-INTEGERS-POWERS-ROOTS', 'Which number has square root 10?', '{"type":"multiple_choice","options":{"A":"100","B":"20","C":"-100","D":"10"},"correct_option":"A","distractor_explanations":{"B":"This doubles instead of squaring.","C":"A positive square root has a positive radicand.","D":"This is the root, not the number."}}', 'If √x = 10, then x = (10)² = 100.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.INT.ENDLINE-REASSESSMENT-B.15', 'G9-T1-INTEGERS-MASTERY-ENDLINE-REASSESSMENT-B', 15, 'G9-NUM-INTEGERS-POWERS-ROOTS', 'Why are brackets important in (−8)²?', '{"type":"multiple_choice","options":{"A":"They make the exponent negative.","B":"They change squaring into multiplication by 2.","C":"They make every answer negative.","D":"They make −8 the base that is multiplied by itself."},"correct_option":"D","distractor_explanations":{"A":"The exponent remains positive 2.","B":"Squaring means multiplying the base by itself.","C":"The square of −8 is positive."}}', '(−8)² = (−8) × (−8) = 64. Without brackets, −8² means −((8)²).', 3, 'mathematical_reasoning', 'complex', 'verbal'),
  ('Q.G9.T1C.INT.ENDLINE-REASSESSMENT-B.16', 'G9-T1-INTEGERS-MASTERY-ENDLINE-REASSESSMENT-B', 16, 'G9-NUM-INTEGERS-OPERATIONS', 'Calculate: |−18| − |7|.', '{"type":"multiple_choice","options":{"A":"25","B":"13","C":"11","D":"-11"},"correct_option":"C","distractor_explanations":{"A":"This adds absolute values.","B":"This changes the second absolute value incorrectly.","D":"This reverses the subtraction."}}', '|−18| = 18 and |7| = 7; 18 − 7 = 11.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.ENTRY.INT.1', 'G9-T1-ENTRY-BASELINE-A', 4, 'G9-NUM-INTEGERS-OPERATIONS', 'Calculate: (−42) ÷ 7.', '{"type":"multiple_choice","options":{"A":"-35","B":"35","C":"-6","D":"6"},"correct_option":"C","distractor_explanations":{"A":"This subtracts instead of divides.","B":"This subtracts and loses the sign.","D":"The magnitude is correct but the sign is lost."}}', 'A negative divided by a positive is negative: −42 ÷ 7 = −6.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.ENTRY.INT.2', 'G9-T1-ENTRY-BASELINE-A', 5, 'G9-NUM-INTEGERS-POWERS-ROOTS', 'Evaluate: −7².', '{"type":"multiple_choice","options":{"A":"14","B":"-49","C":"49","D":"-14"},"correct_option":"B","distractor_explanations":{"A":"This multiplies by 2 and loses the negative.","C":"Without brackets, the exponent is applied before the leading negative.","D":"This multiplies by 2 rather than squaring."}}', 'Exponent first: 7² = 49. The leading negative gives −49.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.ENTRY.INT.3', 'G9-T1-ENTRY-BASELINE-A', 6, 'G9-NUM-INTEGERS-POWERS-ROOTS', 'Evaluate: (−7)².', '{"type":"multiple_choice","options":{"A":"49","B":"-49","C":"-14","D":"14"},"correct_option":"A","distractor_explanations":{"B":"The brackets make the negative number the base, so the product is positive.","C":"This doubles rather than squares.","D":"This doubles rather than squares."}}', '(−7)² = (−7) × (−7) = 49.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.EXP.TOPIC-BASELINE.1', 'G9-T1-EXPONENTS-MASTERY-TOPIC-BASELINE', 1, 'G9-EXP-LAWS-EXTENDED', 'Simplify: x^4 × x^7.', '{"type":"multiple_choice","options":{"A":"x^28","B":"(2x)^11","C":"x^3","D":"x^11"},"correct_option":"D","distractor_explanations":{"A":"This multiplies exponents instead of adding them.","B":"The base remains x; it is not doubled.","C":"This subtracts exponents instead of adding them."}}', 'For equal bases, add exponents: x^4 × x^7 = x^(4 + 7) = x^11.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.EXP.TOPIC-BASELINE.2', 'G9-T1-EXPONENTS-MASTERY-TOPIC-BASELINE', 2, 'G9-EXP-LAWS-EXTENDED', 'Simplify: y^8 ÷ y^4, where y ≠ 0.', '{"type":"multiple_choice","options":{"A":"y²","B":"1/y⁴","C":"y⁴","D":"y^12"},"correct_option":"C","distractor_explanations":{"A":"This halves an exponent rather than applying the quotient law.","B":"The numerator exponent is greater, so the result has positive exponent 4.","D":"This adds exponents instead of subtracting them."}}', 'For equal bases, subtract exponents: y^(8 − 4) = y⁴.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.EXP.TOPIC-BASELINE.3', 'G9-T1-EXPONENTS-MASTERY-TOPIC-BASELINE', 3, 'G9-EXP-LAWS-EXTENDED', 'Simplify: (a^3)^4.', '{"type":"multiple_choice","options":{"A":"a^81","B":"a^12","C":"a^7","D":"(a²)^12"},"correct_option":"B","distractor_explanations":{"A":"The exponent is not raised to a power.","C":"This adds exponents; powers of powers multiply them.","D":"This changes the base without justification."}}', 'A power of a power multiplies exponents: a^(3 × 4) = a^12.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.EXP.TOPIC-BASELINE.4', 'G9-T1-EXPONENTS-MASTERY-TOPIC-BASELINE', 4, 'G9-EXP-NEGATIVE-SCI', 'What is (5)⁰?', '{"type":"multiple_choice","options":{"A":"1","B":"0","C":"5","D":"10"},"correct_option":"A","distractor_explanations":{"B":"A zero exponent does not make a non-zero base zero.","C":"This is the value with exponent 1.","D":"This is unrelated multiplication."}}', 'Any non-zero number divided by itself is 1: (5)¹ ÷ (5)¹ = (5)⁰ = 1.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.EXP.TOPIC-BASELINE.5', 'G9-T1-EXPONENTS-MASTERY-TOPIC-BASELINE', 5, 'G9-EXP-NEGATIVE-SCI', 'What is 2^−3?', '{"type":"multiple_choice","options":{"A":"−8","B":"8","C":"1/3","D":"1/8"},"correct_option":"D","distractor_explanations":{"A":"A negative exponent gives a reciprocal, not a negative value.","B":"This ignores the negative exponent.","C":"The reciprocal applies to the power of 2, not to the exponent."}}', '2^−3 = 1 ÷ 2^3 = 1/8.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.EXP.TOPIC-BASELINE.6', 'G9-T1-EXPONENTS-MASTERY-TOPIC-BASELINE', 6, 'G9-EXP-LAWS-EXTENDED', 'Simplify: (3x²y)^2.', '{"type":"multiple_choice","options":{"A":"9x⁴y","B":"3x⁴y²","C":"9x⁴y²","D":"6x⁴y²"},"correct_option":"C","distractor_explanations":{"A":"The exponent on y must also be multiplied by 2.","B":"The coefficient 3 must be squared.","D":"The coefficient 3 is squared, not doubled."}}', '(3x²y)² = 3² × (x²)² × y² = 9x⁴y².', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.EXP.TOPIC-BASELINE.7', 'G9-T1-EXPONENTS-MASTERY-TOPIC-BASELINE', 7, 'G9-EXP-LAWS-EXTENDED', 'A learner writes 4² × 4³ = 16⁵. Which statement explains the error?', '{"type":"multiple_choice","options":{"A":"The answer is 8⁵ because the bases are added.","B":"The base stays 4; only the exponents are added, giving 4⁵.","C":"The base becomes 5 because 2 + 3 = 5.","D":"The exponents must be multiplied, giving 4⁶."},"correct_option":"B","distractor_explanations":{"A":"Equal bases are not added in this law.","C":"Exponents do not become bases.","D":"Multiplying exponents is for a power of a power, not a product of equal bases."}}', '4² × 4³ = (4 × 4)(4 × 4 × 4) = 4⁵.', 3, 'mathematical_reasoning', 'complex', 'verbal'),
  ('Q.G9.T1C.EXP.TOPIC-BASELINE.8', 'G9-T1-EXPONENTS-MASTERY-TOPIC-BASELINE', 8, 'G9-EXP-NEGATIVE-SCI', 'For which value of z is z⁰ undefined in set 1?', '{"type":"multiple_choice","options":{"A":"z = 0","B":"z = 1","C":"z = −1","D":"z = 5"},"correct_option":"A","distractor_explanations":{"B":"1⁰ = 1.","C":"(−1)⁰ = 1.","D":"Every non-zero number to exponent zero equals 1."}}', 'The zero-exponent rule is derived from z¹ ÷ z¹, which requires z ≠ 0. Therefore 0⁰ is left undefined.', 3, 'mathematical_reasoning', 'complex', 'verbal'),
  ('Q.G9.T1C.EXP.TOPIC-BASELINE.9', 'G9-T1-EXPONENTS-MASTERY-TOPIC-BASELINE', 9, 'G9-EXP-NEGATIVE-SCI', 'Which expression is equivalent to 1/a^2, where a ≠ 0?', '{"type":"multiple_choice","options":{"A":"−a^2","B":"a^2","C":"1/(2a)","D":"a^−2"},"correct_option":"D","distractor_explanations":{"A":"A negative exponent does not make the value negative.","B":"This omits the reciprocal.","C":"The exponent is not a multiplier of a."}}', 'By the negative-exponent rule, a^−2 = 1/a^2.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.EXP.TOPIC-BASELINE.10', 'G9-T1-EXPONENTS-MASTERY-TOPIC-BASELINE', 10, 'G9-EXP-LAWS-EXTENDED', 'Simplify: (m^3n^−2) ÷ m².', '{"type":"multiple_choice","options":{"A":"m^3n⁻4","B":"m^1n⁻2","C":"m^5n⁻2","D":"m^1n^2"},"correct_option":"B","distractor_explanations":{"A":"Only m is divided by m²; n is unchanged.","C":"Dividing by m² subtracts 2 from the m exponent.","D":"The negative exponent on n is retained."}}', 'm^3 ÷ m² = m^(3−2) = m^1, while n⁻2 is unchanged.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.EXP.TOPIC-BASELINE.11', 'G9-T1-EXPONENTS-MASTERY-TOPIC-BASELINE', 11, 'G9-EXP-NEGATIVE-SCI', 'Which method correctly checks that 2⁻² = 1/4?', '{"type":"multiple_choice","options":{"A":"Use 2² × 2⁻² = 2⁰ = 1, so 2⁻² is the reciprocal of 4.","B":"Change the base to −2 and calculate −4.","C":"Subtract 2 from 2 to get −1/4.","D":"Multiply 2 by −2 to get −4."},"correct_option":"A","distractor_explanations":{"B":"The base remains positive.","C":"The exponent is not subtracted from the base.","D":"An exponent is not ordinary multiplication."}}', '2² × 2⁻² = 2^(2−2) = 2⁰ = 1. Thus 2⁻² is the reciprocal of 2², namely 1/4.', 3, 'mathematical_reasoning', 'complex', 'verbal'),
  ('Q.G9.T1C.EXP.TOPIC-BASELINE.12', 'G9-T1-EXPONENTS-MASTERY-TOPIC-BASELINE', 12, 'G9-EXP-LAWS-EXTENDED', 'Simplify: (p²q^3)² ÷ p³q.', '{"type":"multiple_choice","options":{"A":"p⁴q^6","B":"pq^2","C":"p⁷q^7","D":"pq^5"},"correct_option":"D","distractor_explanations":{"A":"This stops before dividing by p³q.","B":"This subtracts the q exponents incorrectly: 6 − 1 = 5.","C":"This adds exponents during division."}}', '(p²q^3)² = p⁴q^6. Dividing by p³q gives p^(4−3)q^(6−1) = pq^5.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.EXP.ENDLINE.1', 'G9-T1-EXPONENTS-MASTERY-ENDLINE', 1, 'G9-EXP-LAWS-EXTENDED', 'Simplify: x^5 × x^8.', '{"type":"multiple_choice","options":{"A":"x^3","B":"x^13","C":"x^40","D":"(2x)^13"},"correct_option":"B","distractor_explanations":{"A":"This subtracts exponents instead of adding them.","C":"This multiplies exponents instead of adding them.","D":"The base remains x; it is not doubled."}}', 'For equal bases, add exponents: x^5 × x^8 = x^(5 + 8) = x^13.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.EXP.ENDLINE.2', 'G9-T1-EXPONENTS-MASTERY-ENDLINE', 2, 'G9-EXP-LAWS-EXTENDED', 'Simplify: y^9 ÷ y^5, where y ≠ 0.', '{"type":"multiple_choice","options":{"A":"y⁴","B":"y^14","C":"y²","D":"1/y⁴"},"correct_option":"A","distractor_explanations":{"B":"This adds exponents instead of subtracting them.","C":"This halves an exponent rather than applying the quotient law.","D":"The numerator exponent is greater, so the result has positive exponent 4."}}', 'For equal bases, subtract exponents: y^(9 − 5) = y⁴.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.EXP.ENDLINE.3', 'G9-T1-EXPONENTS-MASTERY-ENDLINE', 3, 'G9-EXP-LAWS-EXTENDED', 'Simplify: (a^4)^5.', '{"type":"multiple_choice","options":{"A":"a^9","B":"(a²)^20","C":"a^1024","D":"a^20"},"correct_option":"D","distractor_explanations":{"A":"This adds exponents; powers of powers multiply them.","B":"This changes the base without justification.","C":"The exponent is not raised to a power."}}', 'A power of a power multiplies exponents: a^(4 × 5) = a^20.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.EXP.ENDLINE.4', 'G9-T1-EXPONENTS-MASTERY-ENDLINE', 4, 'G9-EXP-NEGATIVE-SCI', 'What is (6)⁰?', '{"type":"multiple_choice","options":{"A":"6","B":"18","C":"1","D":"0"},"correct_option":"C","distractor_explanations":{"A":"This is the value with exponent 1.","B":"This is unrelated multiplication.","D":"A zero exponent does not make a non-zero base zero."}}', 'Any non-zero number divided by itself is 1: (6)¹ ÷ (6)¹ = (6)⁰ = 1.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.EXP.ENDLINE.5', 'G9-T1-EXPONENTS-MASTERY-ENDLINE', 5, 'G9-EXP-NEGATIVE-SCI', 'What is 2^−4?', '{"type":"multiple_choice","options":{"A":"1/4","B":"1/16","C":"−16","D":"16"},"correct_option":"B","distractor_explanations":{"A":"The reciprocal applies to the power of 2, not to the exponent.","C":"A negative exponent gives a reciprocal, not a negative value.","D":"This ignores the negative exponent."}}', '2^−4 = 1 ÷ 2^4 = 1/16.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.EXP.ENDLINE.6', 'G9-T1-EXPONENTS-MASTERY-ENDLINE', 6, 'G9-EXP-LAWS-EXTENDED', 'Simplify: (4x²y)^2.', '{"type":"multiple_choice","options":{"A":"16x⁴y²","B":"8x⁴y²","C":"16x⁴y","D":"4x⁴y²"},"correct_option":"A","distractor_explanations":{"B":"The coefficient 4 is squared, not doubled.","C":"The exponent on y must also be multiplied by 2.","D":"The coefficient 4 must be squared."}}', '(4x²y)² = 4² × (x²)² × y² = 16x⁴y².', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.EXP.ENDLINE.7', 'G9-T1-EXPONENTS-MASTERY-ENDLINE', 7, 'G9-EXP-LAWS-EXTENDED', 'A learner writes 5² × 5³ = 25⁵. Which statement explains the error?', '{"type":"multiple_choice","options":{"A":"The base becomes 5 because 2 + 3 = 5.","B":"The exponents must be multiplied, giving 5⁶.","C":"The answer is 10⁵ because the bases are added.","D":"The base stays 5; only the exponents are added, giving 5⁵."},"correct_option":"D","distractor_explanations":{"A":"Exponents do not become bases.","B":"Multiplying exponents is for a power of a power, not a product of equal bases.","C":"Equal bases are not added in this law."}}', '5² × 5³ = (5 × 5)(5 × 5 × 5) = 5⁵.', 3, 'mathematical_reasoning', 'complex', 'verbal'),
  ('Q.G9.T1C.EXP.ENDLINE.8', 'G9-T1-EXPONENTS-MASTERY-ENDLINE', 8, 'G9-EXP-NEGATIVE-SCI', 'For which value of z is z⁰ undefined in set 2?', '{"type":"multiple_choice","options":{"A":"z = −1","B":"z = 6","C":"z = 0","D":"z = 1"},"correct_option":"C","distractor_explanations":{"A":"(−1)⁰ = 1.","B":"Every non-zero number to exponent zero equals 1.","D":"1⁰ = 1."}}', 'The zero-exponent rule is derived from z¹ ÷ z¹, which requires z ≠ 0. Therefore 0⁰ is left undefined.', 3, 'mathematical_reasoning', 'complex', 'verbal'),
  ('Q.G9.T1C.EXP.ENDLINE.9', 'G9-T1-EXPONENTS-MASTERY-ENDLINE', 9, 'G9-EXP-NEGATIVE-SCI', 'Which expression is equivalent to 1/a^3, where a ≠ 0?', '{"type":"multiple_choice","options":{"A":"1/(3a)","B":"a^−3","C":"−a^3","D":"a^3"},"correct_option":"B","distractor_explanations":{"A":"The exponent is not a multiplier of a.","C":"A negative exponent does not make the value negative.","D":"This omits the reciprocal."}}', 'By the negative-exponent rule, a^−3 = 1/a^3.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.EXP.ENDLINE.10', 'G9-T1-EXPONENTS-MASTERY-ENDLINE', 10, 'G9-EXP-LAWS-EXTENDED', 'Simplify: (m^4n^−3) ÷ m².', '{"type":"multiple_choice","options":{"A":"m^6n⁻3","B":"m^2n^3","C":"m^4n⁻5","D":"m^2n⁻3"},"correct_option":"D","distractor_explanations":{"A":"Dividing by m² subtracts 2 from the m exponent.","B":"The negative exponent on n is retained.","C":"Only m is divided by m²; n is unchanged."}}', 'm^4 ÷ m² = m^(4−2) = m^2, while n⁻3 is unchanged.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.EXP.ENDLINE.11', 'G9-T1-EXPONENTS-MASTERY-ENDLINE', 11, 'G9-EXP-NEGATIVE-SCI', 'Which method correctly checks that 3⁻² = 1/9?', '{"type":"multiple_choice","options":{"A":"Subtract 2 from 3 to get −1/9.","B":"Multiply 3 by −2 to get −6.","C":"Use 3² × 3⁻² = 3⁰ = 1, so 3⁻² is the reciprocal of 9.","D":"Change the base to −3 and calculate −9."},"correct_option":"C","distractor_explanations":{"A":"The exponent is not subtracted from the base.","B":"An exponent is not ordinary multiplication.","D":"The base remains positive."}}', '3² × 3⁻² = 3^(2−2) = 3⁰ = 1. Thus 3⁻² is the reciprocal of 3², namely 1/9.', 3, 'mathematical_reasoning', 'complex', 'verbal'),
  ('Q.G9.T1C.EXP.ENDLINE.12', 'G9-T1-EXPONENTS-MASTERY-ENDLINE', 12, 'G9-EXP-LAWS-EXTENDED', 'Simplify: (p²q^4)² ÷ p³q.', '{"type":"multiple_choice","options":{"A":"p⁷q^9","B":"pq^7","C":"p⁴q^8","D":"pq^3"},"correct_option":"B","distractor_explanations":{"A":"This adds exponents during division.","C":"This stops before dividing by p³q.","D":"This subtracts the q exponents incorrectly: 8 − 1 = 7."}}', '(p²q^4)² = p⁴q^8. Dividing by p³q gives p^(4−3)q^(8−1) = pq^7.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.EXP.ENDLINE.13', 'G9-T1-EXPONENTS-MASTERY-ENDLINE', 13, 'G9-EXP-LAWS-EXTENDED', 'Is the statement (xy)^3 = x^3y^3 always, sometimes or never true for real x and y?', '{"type":"multiple_choice","options":{"A":"Always true for real numbers x and y.","B":"Never true because exponents cannot be distributed.","C":"Sometimes true only when x = y.","D":"Sometimes true only when x and y are positive."},"correct_option":"A","distractor_explanations":{"B":"A product raised to a positive integer power distributes over multiplication.","C":"The rule does not require equal factors.","D":"A positive integer power is defined for negative real factors too."}}', '(xy)^3 repeats xy as a factor 3 times, so factors can be regrouped as x^3y^3.', 3, 'mathematical_reasoning', 'complex', 'verbal'),
  ('Q.G9.T1C.EXP.ENDLINE.14', 'G9-T1-EXPONENTS-MASTERY-ENDLINE', 14, 'G9-EXP-LAWS-EXTENDED', 'Which expression has the same value as 4^3 × 2^6?', '{"type":"multiple_choice","options":{"A":"8^3","B":"2^9","C":"2^6","D":"2^12"},"correct_option":"D","distractor_explanations":{"A":"4^n × 2^(2n) = 2^(2n) × 2^(2n), not 2^(3n).","B":"This treats 4^n as 2^n instead of 2^(2n).","C":"This ignores one factor."}}', '4^3 = (2²)^3 = 2^6. Multiplying by 2^6 gives 2^12.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.EXP.ENDLINE.15', 'G9-T1-EXPONENTS-MASTERY-ENDLINE', 15, 'G9-EXP-LAWS-EXTENDED', 'Why must r ≠ 0 be stated for r^6 ÷ r^3 = r³?', '{"type":"multiple_choice","options":{"A":"Because r³ is never zero.","B":"Because exponents cannot be subtracted.","C":"Division by r^3 would be division by zero when r = 0.","D":"Because zero cannot have an exponent."},"correct_option":"C","distractor_explanations":{"A":"r³ is zero when r = 0.","B":"Exponents are subtracted in the quotient law when division is defined.","D":"Zero can have positive exponents."}}', 'The quotient r^6 ÷ r^3 is defined only if r^3 ≠ 0. Therefore r must not be 0.', 3, 'mathematical_reasoning', 'complex', 'verbal'),
  ('Q.G9.T1C.EXP.ENDLINE.16', 'G9-T1-EXPONENTS-MASTERY-ENDLINE', 16, 'G9-EXP-LAWS-EXTENDED', 'Simplify: (−2)² × 2^3.', '{"type":"multiple_choice","options":{"A":"8","B":"32","C":"−32","D":"64"},"correct_option":"B","distractor_explanations":{"A":"This ignores the factor (−2)² = 4.","C":"The squared negative base is positive.","D":"Exponents are added, not multiplied, after evaluating (−2)² as 2²."}}', '(−2)² = 4 = 2². Thus 2² × 2^3 = 2^5.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.EXP.MASTERY-CHALLENGE.1', 'G9-T1-EXPONENTS-MASTERY-CHALLENGE', 1, 'G9-EXP-LAWS-EXTENDED', 'Simplify: x^6 × x^9.', '{"type":"multiple_choice","options":{"A":"x^54","B":"(2x)^15","C":"x^3","D":"x^15"},"correct_option":"D","distractor_explanations":{"A":"This multiplies exponents instead of adding them.","B":"The base remains x; it is not doubled.","C":"This subtracts exponents instead of adding them."}}', 'For equal bases, add exponents: x^6 × x^9 = x^(6 + 9) = x^15.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.EXP.MASTERY-CHALLENGE.2', 'G9-T1-EXPONENTS-MASTERY-CHALLENGE', 2, 'G9-EXP-LAWS-EXTENDED', 'Simplify: y^10 ÷ y^6, where y ≠ 0.', '{"type":"multiple_choice","options":{"A":"y²","B":"1/y⁴","C":"y⁴","D":"y^16"},"correct_option":"C","distractor_explanations":{"A":"This halves an exponent rather than applying the quotient law.","B":"The numerator exponent is greater, so the result has positive exponent 4.","D":"This adds exponents instead of subtracting them."}}', 'For equal bases, subtract exponents: y^(10 − 6) = y⁴.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.EXP.MASTERY-CHALLENGE.3', 'G9-T1-EXPONENTS-MASTERY-CHALLENGE', 3, 'G9-EXP-LAWS-EXTENDED', 'Simplify: (a^5)^6.', '{"type":"multiple_choice","options":{"A":"a^15625","B":"a^30","C":"a^11","D":"(a²)^30"},"correct_option":"B","distractor_explanations":{"A":"The exponent is not raised to a power.","C":"This adds exponents; powers of powers multiply them.","D":"This changes the base without justification."}}', 'A power of a power multiplies exponents: a^(5 × 6) = a^30.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.EXP.MASTERY-CHALLENGE.4', 'G9-T1-EXPONENTS-MASTERY-CHALLENGE', 4, 'G9-EXP-NEGATIVE-SCI', 'What is (7)⁰?', '{"type":"multiple_choice","options":{"A":"1","B":"0","C":"7","D":"28"},"correct_option":"A","distractor_explanations":{"B":"A zero exponent does not make a non-zero base zero.","C":"This is the value with exponent 1.","D":"This is unrelated multiplication."}}', 'Any non-zero number divided by itself is 1: (7)¹ ÷ (7)¹ = (7)⁰ = 1.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.EXP.MASTERY-CHALLENGE.5', 'G9-T1-EXPONENTS-MASTERY-CHALLENGE', 5, 'G9-EXP-NEGATIVE-SCI', 'What is 2^−5?', '{"type":"multiple_choice","options":{"A":"−32","B":"32","C":"1/5","D":"1/32"},"correct_option":"D","distractor_explanations":{"A":"A negative exponent gives a reciprocal, not a negative value.","B":"This ignores the negative exponent.","C":"The reciprocal applies to the power of 2, not to the exponent."}}', '2^−5 = 1 ÷ 2^5 = 1/32.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.EXP.MASTERY-CHALLENGE.6', 'G9-T1-EXPONENTS-MASTERY-CHALLENGE', 6, 'G9-EXP-LAWS-EXTENDED', 'Simplify: (5x²y)^2.', '{"type":"multiple_choice","options":{"A":"25x⁴y","B":"5x⁴y²","C":"25x⁴y²","D":"10x⁴y²"},"correct_option":"C","distractor_explanations":{"A":"The exponent on y must also be multiplied by 2.","B":"The coefficient 5 must be squared.","D":"The coefficient 5 is squared, not doubled."}}', '(5x²y)² = 5² × (x²)² × y² = 25x⁴y².', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.EXP.MASTERY-CHALLENGE.7', 'G9-T1-EXPONENTS-MASTERY-CHALLENGE', 7, 'G9-EXP-LAWS-EXTENDED', 'A learner writes 6² × 6³ = 36⁵. Which statement explains the error?', '{"type":"multiple_choice","options":{"A":"The answer is 12⁵ because the bases are added.","B":"The base stays 6; only the exponents are added, giving 6⁵.","C":"The base becomes 5 because 2 + 3 = 5.","D":"The exponents must be multiplied, giving 6⁶."},"correct_option":"B","distractor_explanations":{"A":"Equal bases are not added in this law.","C":"Exponents do not become bases.","D":"Multiplying exponents is for a power of a power, not a product of equal bases."}}', '6² × 6³ = (6 × 6)(6 × 6 × 6) = 6⁵.', 3, 'mathematical_reasoning', 'complex', 'verbal'),
  ('Q.G9.T1C.EXP.MASTERY-CHALLENGE.8', 'G9-T1-EXPONENTS-MASTERY-CHALLENGE', 8, 'G9-EXP-NEGATIVE-SCI', 'For which value of z is z⁰ undefined in set 3?', '{"type":"multiple_choice","options":{"A":"z = 0","B":"z = 1","C":"z = −1","D":"z = 7"},"correct_option":"A","distractor_explanations":{"B":"1⁰ = 1.","C":"(−1)⁰ = 1.","D":"Every non-zero number to exponent zero equals 1."}}', 'The zero-exponent rule is derived from z¹ ÷ z¹, which requires z ≠ 0. Therefore 0⁰ is left undefined.', 3, 'mathematical_reasoning', 'complex', 'verbal'),
  ('Q.G9.T1C.EXP.MASTERY-CHALLENGE.9', 'G9-T1-EXPONENTS-MASTERY-CHALLENGE', 9, 'G9-EXP-NEGATIVE-SCI', 'Which expression is equivalent to 1/a^4, where a ≠ 0?', '{"type":"multiple_choice","options":{"A":"−a^4","B":"a^4","C":"1/(4a)","D":"a^−4"},"correct_option":"D","distractor_explanations":{"A":"A negative exponent does not make the value negative.","B":"This omits the reciprocal.","C":"The exponent is not a multiplier of a."}}', 'By the negative-exponent rule, a^−4 = 1/a^4.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.EXP.MASTERY-CHALLENGE.10', 'G9-T1-EXPONENTS-MASTERY-CHALLENGE', 10, 'G9-EXP-LAWS-EXTENDED', 'Simplify: (m^5n^−4) ÷ m².', '{"type":"multiple_choice","options":{"A":"m^5n⁻6","B":"m^3n⁻4","C":"m^7n⁻4","D":"m^3n^4"},"correct_option":"B","distractor_explanations":{"A":"Only m is divided by m²; n is unchanged.","C":"Dividing by m² subtracts 2 from the m exponent.","D":"The negative exponent on n is retained."}}', 'm^5 ÷ m² = m^(5−2) = m^3, while n⁻4 is unchanged.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.EXP.MASTERY-CHALLENGE.11', 'G9-T1-EXPONENTS-MASTERY-CHALLENGE', 11, 'G9-EXP-NEGATIVE-SCI', 'Which method correctly checks that 4⁻² = 1/16?', '{"type":"multiple_choice","options":{"A":"Use 4² × 4⁻² = 4⁰ = 1, so 4⁻² is the reciprocal of 16.","B":"Change the base to −4 and calculate −16.","C":"Subtract 2 from 4 to get −1/16.","D":"Multiply 4 by −2 to get −8."},"correct_option":"A","distractor_explanations":{"B":"The base remains positive.","C":"The exponent is not subtracted from the base.","D":"An exponent is not ordinary multiplication."}}', '4² × 4⁻² = 4^(2−2) = 4⁰ = 1. Thus 4⁻² is the reciprocal of 4², namely 1/16.', 3, 'mathematical_reasoning', 'complex', 'verbal'),
  ('Q.G9.T1C.EXP.MASTERY-CHALLENGE.12', 'G9-T1-EXPONENTS-MASTERY-CHALLENGE', 12, 'G9-EXP-LAWS-EXTENDED', 'Simplify: (p²q^5)² ÷ p³q.', '{"type":"multiple_choice","options":{"A":"p⁴q^10","B":"pq^4","C":"p⁷q^11","D":"pq^9"},"correct_option":"D","distractor_explanations":{"A":"This stops before dividing by p³q.","B":"This subtracts the q exponents incorrectly: 10 − 1 = 9.","C":"This adds exponents during division."}}', '(p²q^5)² = p⁴q^10. Dividing by p³q gives p^(4−3)q^(10−1) = pq^9.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.EXP.MASTERY-CHALLENGE.13', 'G9-T1-EXPONENTS-MASTERY-CHALLENGE', 13, 'G9-EXP-LAWS-EXTENDED', 'Is the statement (xy)^4 = x^4y^4 always, sometimes or never true for real x and y?', '{"type":"multiple_choice","options":{"A":"Sometimes true only when x = y.","B":"Sometimes true only when x and y are positive.","C":"Always true for real numbers x and y.","D":"Never true because exponents cannot be distributed."},"correct_option":"C","distractor_explanations":{"A":"The rule does not require equal factors.","B":"A positive integer power is defined for negative real factors too.","D":"A product raised to a positive integer power distributes over multiplication."}}', '(xy)^4 repeats xy as a factor 4 times, so factors can be regrouped as x^4y^4.', 3, 'mathematical_reasoning', 'complex', 'verbal'),
  ('Q.G9.T1C.EXP.MASTERY-CHALLENGE.14', 'G9-T1-EXPONENTS-MASTERY-CHALLENGE', 14, 'G9-EXP-LAWS-EXTENDED', 'Which expression has the same value as 4^4 × 2^8?', '{"type":"multiple_choice","options":{"A":"2^8","B":"2^16","C":"8^4","D":"2^12"},"correct_option":"B","distractor_explanations":{"A":"This ignores one factor.","C":"4^n × 2^(2n) = 2^(2n) × 2^(2n), not 2^(3n).","D":"This treats 4^n as 2^n instead of 2^(2n)."}}', '4^4 = (2²)^4 = 2^8. Multiplying by 2^8 gives 2^16.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.EXP.MASTERY-CHALLENGE.15', 'G9-T1-EXPONENTS-MASTERY-CHALLENGE', 15, 'G9-EXP-LAWS-EXTENDED', 'Why must r ≠ 0 be stated for r^7 ÷ r^4 = r³?', '{"type":"multiple_choice","options":{"A":"Division by r^4 would be division by zero when r = 0.","B":"Because zero cannot have an exponent.","C":"Because r³ is never zero.","D":"Because exponents cannot be subtracted."},"correct_option":"A","distractor_explanations":{"B":"Zero can have positive exponents.","C":"r³ is zero when r = 0.","D":"Exponents are subtracted in the quotient law when division is defined."}}', 'The quotient r^7 ÷ r^4 is defined only if r^4 ≠ 0. Therefore r must not be 0.', 3, 'mathematical_reasoning', 'complex', 'verbal'),
  ('Q.G9.T1C.EXP.MASTERY-CHALLENGE.16', 'G9-T1-EXPONENTS-MASTERY-CHALLENGE', 16, 'G9-EXP-LAWS-EXTENDED', 'Simplify: (−2)² × 2^4.', '{"type":"multiple_choice","options":{"A":"−64","B":"256","C":"16","D":"64"},"correct_option":"D","distractor_explanations":{"A":"The squared negative base is positive.","B":"Exponents are added, not multiplied, after evaluating (−2)² as 2².","C":"This ignores the factor (−2)² = 4."}}', '(−2)² = 4 = 2². Thus 2² × 2^4 = 2^6.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.EXP.ENDLINE-REASSESSMENT-B.1', 'G9-T1-EXPONENTS-MASTERY-ENDLINE-REASSESSMENT-B', 1, 'G9-EXP-LAWS-EXTENDED', 'Simplify: x^7 × x^10.', '{"type":"multiple_choice","options":{"A":"(2x)^17","B":"x^3","C":"x^17","D":"x^70"},"correct_option":"C","distractor_explanations":{"A":"The base remains x; it is not doubled.","B":"This subtracts exponents instead of adding them.","D":"This multiplies exponents instead of adding them."}}', 'For equal bases, add exponents: x^7 × x^10 = x^(7 + 10) = x^17.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.EXP.ENDLINE-REASSESSMENT-B.2', 'G9-T1-EXPONENTS-MASTERY-ENDLINE-REASSESSMENT-B', 2, 'G9-EXP-LAWS-EXTENDED', 'Simplify: y^11 ÷ y^7, where y ≠ 0.', '{"type":"multiple_choice","options":{"A":"1/y⁴","B":"y⁴","C":"y^18","D":"y²"},"correct_option":"B","distractor_explanations":{"A":"The numerator exponent is greater, so the result has positive exponent 4.","C":"This adds exponents instead of subtracting them.","D":"This halves an exponent rather than applying the quotient law."}}', 'For equal bases, subtract exponents: y^(11 − 7) = y⁴.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.EXP.ENDLINE-REASSESSMENT-B.3', 'G9-T1-EXPONENTS-MASTERY-ENDLINE-REASSESSMENT-B', 3, 'G9-EXP-LAWS-EXTENDED', 'Simplify: (a^6)^7.', '{"type":"multiple_choice","options":{"A":"a^42","B":"a^13","C":"(a²)^42","D":"a^279936"},"correct_option":"A","distractor_explanations":{"B":"This adds exponents; powers of powers multiply them.","C":"This changes the base without justification.","D":"The exponent is not raised to a power."}}', 'A power of a power multiplies exponents: a^(6 × 7) = a^42.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.EXP.ENDLINE-REASSESSMENT-B.4', 'G9-T1-EXPONENTS-MASTERY-ENDLINE-REASSESSMENT-B', 4, 'G9-EXP-NEGATIVE-SCI', 'What is (8)⁰?', '{"type":"multiple_choice","options":{"A":"0","B":"8","C":"40","D":"1"},"correct_option":"D","distractor_explanations":{"A":"A zero exponent does not make a non-zero base zero.","B":"This is the value with exponent 1.","C":"This is unrelated multiplication."}}', 'Any non-zero number divided by itself is 1: (8)¹ ÷ (8)¹ = (8)⁰ = 1.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.EXP.ENDLINE-REASSESSMENT-B.5', 'G9-T1-EXPONENTS-MASTERY-ENDLINE-REASSESSMENT-B', 5, 'G9-EXP-NEGATIVE-SCI', 'What is 2^−6?', '{"type":"multiple_choice","options":{"A":"64","B":"1/6","C":"1/64","D":"−64"},"correct_option":"C","distractor_explanations":{"A":"This ignores the negative exponent.","B":"The reciprocal applies to the power of 2, not to the exponent.","D":"A negative exponent gives a reciprocal, not a negative value."}}', '2^−6 = 1 ÷ 2^6 = 1/64.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.EXP.ENDLINE-REASSESSMENT-B.6', 'G9-T1-EXPONENTS-MASTERY-ENDLINE-REASSESSMENT-B', 6, 'G9-EXP-LAWS-EXTENDED', 'Simplify: (6x²y)^2.', '{"type":"multiple_choice","options":{"A":"6x⁴y²","B":"36x⁴y²","C":"12x⁴y²","D":"36x⁴y"},"correct_option":"B","distractor_explanations":{"A":"The coefficient 6 must be squared.","C":"The coefficient 6 is squared, not doubled.","D":"The exponent on y must also be multiplied by 2."}}', '(6x²y)² = 6² × (x²)² × y² = 36x⁴y².', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.EXP.ENDLINE-REASSESSMENT-B.7', 'G9-T1-EXPONENTS-MASTERY-ENDLINE-REASSESSMENT-B', 7, 'G9-EXP-LAWS-EXTENDED', 'A learner writes 7² × 7³ = 49⁵. Which statement explains the error?', '{"type":"multiple_choice","options":{"A":"The base stays 7; only the exponents are added, giving 7⁵.","B":"The base becomes 5 because 2 + 3 = 5.","C":"The exponents must be multiplied, giving 7⁶.","D":"The answer is 14⁵ because the bases are added."},"correct_option":"A","distractor_explanations":{"B":"Exponents do not become bases.","C":"Multiplying exponents is for a power of a power, not a product of equal bases.","D":"Equal bases are not added in this law."}}', '7² × 7³ = (7 × 7)(7 × 7 × 7) = 7⁵.', 3, 'mathematical_reasoning', 'complex', 'verbal'),
  ('Q.G9.T1C.EXP.ENDLINE-REASSESSMENT-B.8', 'G9-T1-EXPONENTS-MASTERY-ENDLINE-REASSESSMENT-B', 8, 'G9-EXP-NEGATIVE-SCI', 'For which value of z is z⁰ undefined in set 4?', '{"type":"multiple_choice","options":{"A":"z = 1","B":"z = −1","C":"z = 8","D":"z = 0"},"correct_option":"D","distractor_explanations":{"A":"1⁰ = 1.","B":"(−1)⁰ = 1.","C":"Every non-zero number to exponent zero equals 1."}}', 'The zero-exponent rule is derived from z¹ ÷ z¹, which requires z ≠ 0. Therefore 0⁰ is left undefined.', 3, 'mathematical_reasoning', 'complex', 'verbal'),
  ('Q.G9.T1C.EXP.ENDLINE-REASSESSMENT-B.9', 'G9-T1-EXPONENTS-MASTERY-ENDLINE-REASSESSMENT-B', 9, 'G9-EXP-NEGATIVE-SCI', 'Which expression is equivalent to 1/a^5, where a ≠ 0?', '{"type":"multiple_choice","options":{"A":"a^5","B":"1/(5a)","C":"a^−5","D":"−a^5"},"correct_option":"C","distractor_explanations":{"A":"This omits the reciprocal.","B":"The exponent is not a multiplier of a.","D":"A negative exponent does not make the value negative."}}', 'By the negative-exponent rule, a^−5 = 1/a^5.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.EXP.ENDLINE-REASSESSMENT-B.10', 'G9-T1-EXPONENTS-MASTERY-ENDLINE-REASSESSMENT-B', 10, 'G9-EXP-LAWS-EXTENDED', 'Simplify: (m^6n^−5) ÷ m².', '{"type":"multiple_choice","options":{"A":"m^4n^5","B":"m^6n⁻7","C":"m^4n⁻5","D":"m^8n⁻5"},"correct_option":"C","distractor_explanations":{"A":"The negative exponent on n is retained.","B":"Only m is divided by m²; n is unchanged.","D":"Dividing by m² subtracts 2 from the m exponent."}}', 'm^6 ÷ m² = m^(6−2) = m^4, while n⁻5 is unchanged.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.EXP.ENDLINE-REASSESSMENT-B.11', 'G9-T1-EXPONENTS-MASTERY-ENDLINE-REASSESSMENT-B', 11, 'G9-EXP-NEGATIVE-SCI', 'Which method correctly checks that 5⁻² = 1/25?', '{"type":"multiple_choice","options":{"A":"Multiply 5 by −2 to get −10.","B":"Use 5² × 5⁻² = 5⁰ = 1, so 5⁻² is the reciprocal of 25.","C":"Change the base to −5 and calculate −25.","D":"Subtract 2 from 5 to get −1/25."},"correct_option":"B","distractor_explanations":{"A":"An exponent is not ordinary multiplication.","C":"The base remains positive.","D":"The exponent is not subtracted from the base."}}', '5² × 5⁻² = 5^(2−2) = 5⁰ = 1. Thus 5⁻² is the reciprocal of 5², namely 1/25.', 3, 'mathematical_reasoning', 'complex', 'verbal'),
  ('Q.G9.T1C.EXP.ENDLINE-REASSESSMENT-B.12', 'G9-T1-EXPONENTS-MASTERY-ENDLINE-REASSESSMENT-B', 12, 'G9-EXP-LAWS-EXTENDED', 'Simplify: (p²q^6)² ÷ p³q.', '{"type":"multiple_choice","options":{"A":"pq^11","B":"p⁴q^12","C":"pq^5","D":"p⁷q^13"},"correct_option":"A","distractor_explanations":{"B":"This stops before dividing by p³q.","C":"This subtracts the q exponents incorrectly: 12 − 1 = 11.","D":"This adds exponents during division."}}', '(p²q^6)² = p⁴q^12. Dividing by p³q gives p^(4−3)q^(12−1) = pq^11.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.EXP.ENDLINE-REASSESSMENT-B.13', 'G9-T1-EXPONENTS-MASTERY-ENDLINE-REASSESSMENT-B', 13, 'G9-EXP-LAWS-EXTENDED', 'Is the statement (xy)^5 = x^5y^5 always, sometimes or never true for real x and y?', '{"type":"multiple_choice","options":{"A":"Never true because exponents cannot be distributed.","B":"Sometimes true only when x = y.","C":"Sometimes true only when x and y are positive.","D":"Always true for real numbers x and y."},"correct_option":"D","distractor_explanations":{"A":"A product raised to a positive integer power distributes over multiplication.","B":"The rule does not require equal factors.","C":"A positive integer power is defined for negative real factors too."}}', '(xy)^5 repeats xy as a factor 5 times, so factors can be regrouped as x^5y^5.', 3, 'mathematical_reasoning', 'complex', 'verbal'),
  ('Q.G9.T1C.EXP.ENDLINE-REASSESSMENT-B.14', 'G9-T1-EXPONENTS-MASTERY-ENDLINE-REASSESSMENT-B', 14, 'G9-EXP-LAWS-EXTENDED', 'Which expression has the same value as 4^5 × 2^10?', '{"type":"multiple_choice","options":{"A":"2^15","B":"2^10","C":"2^20","D":"8^5"},"correct_option":"C","distractor_explanations":{"A":"This treats 4^n as 2^n instead of 2^(2n).","B":"This ignores one factor.","D":"4^n × 2^(2n) = 2^(2n) × 2^(2n), not 2^(3n)."}}', '4^5 = (2²)^5 = 2^10. Multiplying by 2^10 gives 2^20.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.EXP.ENDLINE-REASSESSMENT-B.15', 'G9-T1-EXPONENTS-MASTERY-ENDLINE-REASSESSMENT-B', 15, 'G9-EXP-LAWS-EXTENDED', 'Why must r ≠ 0 be stated for r^8 ÷ r^5 = r³?', '{"type":"multiple_choice","options":{"A":"Because exponents cannot be subtracted.","B":"Division by r^5 would be division by zero when r = 0.","C":"Because zero cannot have an exponent.","D":"Because r³ is never zero."},"correct_option":"B","distractor_explanations":{"A":"Exponents are subtracted in the quotient law when division is defined.","C":"Zero can have positive exponents.","D":"r³ is zero when r = 0."}}', 'The quotient r^8 ÷ r^5 is defined only if r^5 ≠ 0. Therefore r must not be 0.', 3, 'mathematical_reasoning', 'complex', 'verbal'),
  ('Q.G9.T1C.EXP.ENDLINE-REASSESSMENT-B.16', 'G9-T1-EXPONENTS-MASTERY-ENDLINE-REASSESSMENT-B', 16, 'G9-EXP-LAWS-EXTENDED', 'Simplify: (−2)² × 2^5.', '{"type":"multiple_choice","options":{"A":"128","B":"−128","C":"1024","D":"32"},"correct_option":"A","distractor_explanations":{"B":"The squared negative base is positive.","C":"Exponents are added, not multiplied, after evaluating (−2)² as 2².","D":"This ignores the factor (−2)² = 4."}}', '(−2)² = 4 = 2². Thus 2² × 2^5 = 2^7.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.ENTRY.EXP.1', 'G9-T1-ENTRY-BASELINE-A', 7, 'G9-EXP-NEGATIVE-SCI', 'What is (9)⁰?', '{"type":"multiple_choice","options":{"A":"0","B":"9","C":"54","D":"1"},"correct_option":"D","distractor_explanations":{"A":"A zero exponent does not make a non-zero base zero.","B":"This is the value with exponent 1.","C":"This is unrelated multiplication."}}', 'Any non-zero number divided by itself is 1: (9)¹ ÷ (9)¹ = (9)⁰ = 1.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.ENTRY.EXP.2', 'G9-T1-ENTRY-BASELINE-A', 8, 'G9-EXP-NEGATIVE-SCI', 'What is 2^−7?', '{"type":"multiple_choice","options":{"A":"128","B":"1/7","C":"1/128","D":"−128"},"correct_option":"C","distractor_explanations":{"A":"This ignores the negative exponent.","B":"The reciprocal applies to the power of 2, not to the exponent.","D":"A negative exponent gives a reciprocal, not a negative value."}}', '2^−7 = 1 ÷ 2^7 = 1/128.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.ENTRY.EXP.3', 'G9-T1-ENTRY-BASELINE-A', 9, 'G9-EXP-LAWS-EXTENDED', 'Simplify: (7x²y)^2.', '{"type":"multiple_choice","options":{"A":"7x⁴y²","B":"49x⁴y²","C":"14x⁴y²","D":"49x⁴y"},"correct_option":"B","distractor_explanations":{"A":"The coefficient 7 must be squared.","C":"The coefficient 7 is squared, not doubled.","D":"The exponent on y must also be multiplied by 2."}}', '(7x²y)² = 7² × (x²)² × y² = 49x⁴y².', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.PAT.TOPIC-BASELINE.1', 'G9-T1-PATTERNS-MASTERY-TOPIC-BASELINE', 1, 'G9-PAT-NUMERIC-STRUCTURE', 'The pattern is 3, 5, 7, … . What is the first difference?', '{"type":"multiple_choice","options":{"A":"1","B":"2","C":"3","D":"4"},"correct_option":"B","distractor_explanations":{"A":"This is only the constant part.","C":"This is the first term, not the difference.","D":"This is the second term without its constant adjustment."}}', 'Subtract consecutive terms: (5) − (3) = 2.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.PAT.TOPIC-BASELINE.2', 'G9-T1-PATTERNS-MASTERY-TOPIC-BASELINE', 2, 'G9-PAT-GENERAL-RULE', 'The pattern is 5, 7, 9, … . Which rule gives Tn?', '{"type":"multiple_choice","options":{"A":"2n + 3","B":"2n + 5","C":"5n","D":"n + 4"},"correct_option":"A","distractor_explanations":{"B":"This uses the first term as the constant without checking n = 1.","C":"This gives the wrong first difference.","D":"This has first difference 1 rather than 2."}}', 'The difference is 2. Let Tn = 2n + c. At n = 1, 2 + c = 5, so c = 3.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.PAT.TOPIC-BASELINE.3', 'G9-T1-PATTERNS-MASTERY-TOPIC-BASELINE', 3, 'G9-PAT-NUMERIC-STRUCTURE', 'A table gives n: 1, 2, 3 and Tn: 5, 7, 9. What is T10?', '{"type":"multiple_choice","options":{"A":"21","B":"22","C":"30","D":"23"},"correct_option":"D","distractor_explanations":{"A":"This omits the first-term adjustment.","B":"This omits the constant +1.","C":"This uses an unrelated constant."}}', 'The rule is Tn = 2n + 3? Check: at n=1 this is 5; therefore T10 = 23.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.PAT.TOPIC-BASELINE.4', 'G9-T1-PATTERNS-MASTERY-TOPIC-BASELINE', 4, 'G9-PAT-GENERAL-RULE', 'For Tn = 3n − 2, what is T6?', '{"type":"multiple_choice","options":{"A":"7","B":"20","C":"16","D":"18"},"correct_option":"C","distractor_explanations":{"A":"This adds n and the coefficient instead of multiplying.","B":"This uses +2 rather than −2.","D":"This omits the −2."}}', 'Substitute n = 6: T6 = 3(6) − 2 = 16.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.PAT.TOPIC-BASELINE.5', 'G9-T1-PATTERNS-MASTERY-TOPIC-BASELINE', 5, 'G9-PAT-GEOMETRIC-VISUAL', 'A diagram in set 1 shows n joined unit squares in one row, sharing full sides. Which rule gives its matchsticks M?', '{"type":"multiple_choice","options":{"A":"M = n + 3","B":"M = 3n + 1","C":"M = 4n","D":"M = 3n"},"correct_option":"B","distractor_explanations":{"A":"This adds only one matchstick per additional square.","C":"This counts shared sides twice.","D":"This omits the one extra side at the end."}}', 'One square needs 4 matchsticks. Each additional square shares one side and adds 3. Thus M = 4 + 3(n−1) = 3n + 1.', 3, 'mathematical_reasoning', 'complex', 'verbal'),
  ('Q.G9.T1C.PAT.TOPIC-BASELINE.6', 'G9-T1-PATTERNS-MASTERY-TOPIC-BASELINE', 6, 'G9-PAT-GEOMETRIC-VISUAL', 'Using M = 3n + 1 for a row of joined squares, how many matchsticks are needed for n = 8?', '{"type":"multiple_choice","options":{"A":"25","B":"32","C":"24","D":"11"},"correct_option":"A","distractor_explanations":{"B":"This counts every square as isolated.","C":"This omits the +1.","D":"This adds rather than multiplies the figure number."}}', 'Substitute n = 8: M = 3(8) + 1 = 25.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.PAT.TOPIC-BASELINE.7', 'G9-T1-PATTERNS-MASTERY-TOPIC-BASELINE', 7, 'G9-PAT-GENERAL-RULE', 'A learner says the pattern 4, 7, 10, … has rule Tn = 3n + 4. What is the best correction?', '{"type":"multiple_choice","options":{"A":"Tn = 3n − 4","B":"Tn = 4n + 3","C":"Tn = 3n","D":"Tn = 3n + 1, because T1 must equal 4."},"correct_option":"D","distractor_explanations":{"A":"At n = 1 this gives -1, not 4.","B":"This gives first difference 4, not 3.","C":"This gives T1 = 3, so the constant is missing."}}', 'Use Tn = 3n + c. Since T1 = 4, 3 + c = 4, so c = 1.', 3, 'mathematical_reasoning', 'complex', 'verbal'),
  ('Q.G9.T1C.PAT.TOPIC-BASELINE.8', 'G9-T1-PATTERNS-MASTERY-TOPIC-BASELINE', 8, 'G9-PAT-NUMERIC-STRUCTURE', 'A pattern has rule Tn = 2n + 4. Which table row is correct?', '{"type":"multiple_choice","options":{"A":"n = 3, Tn = 6","B":"n = 3, Tn = 2","C":"n = 3, Tn = 10","D":"n = 3, Tn = 9"},"correct_option":"C","distractor_explanations":{"A":"This omits the constant 4.","B":"This subtracts the constant instead of adding it.","D":"This adds the coefficient and n instead of multiplying."}}', 'Substitute n = 3: T3 = 2(3) + 4 = 10.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.PAT.TOPIC-BASELINE.9', 'G9-T1-PATTERNS-MASTERY-TOPIC-BASELINE', 9, 'G9-PAT-NUMERIC-STRUCTURE', 'The first differences are 2, 2, 2. What can be concluded about the sequence?', '{"type":"multiple_choice","options":{"A":"Its rule must be n² + c.","B":"It is linear and has an nth-term rule of the form 2n + c.","C":"It is quadratic because it has differences.","D":"It is exponential because terms change."},"correct_option":"B","distractor_explanations":{"A":"A squared rule has changing first differences.","C":"A constant first difference indicates a linear pattern.","D":"Exponential patterns have a constant ratio, not constant first difference."}}', 'A linear sequence changes by a constant amount. Its coefficient of n equals the constant first difference 2.', 3, 'mathematical_reasoning', 'complex', 'verbal'),
  ('Q.G9.T1C.PAT.TOPIC-BASELINE.10', 'G9-T1-PATTERNS-MASTERY-TOPIC-BASELINE', 10, 'G9-PAT-GEOMETRIC-VISUAL', 'Figure 1 in tile set 1 uses 5 tiles. Each new figure adds 4 tiles. Which expression gives figure n?', '{"type":"multiple_choice","options":{"A":"5n","B":"4n + 5","C":"n + 4","D":"4n + 1"},"correct_option":"D","distractor_explanations":{"A":"This adds 5 each time instead of 4.","B":"At n = 1 this gives 9, not 5.","C":"This adds only 1 each time."}}', 'Tn = 5 + 4(n−1) = 5 + 4n − 4 = 4n + 1.', 3, 'mathematical_reasoning', 'complex', 'verbal'),
  ('Q.G9.T1C.PAT.TOPIC-BASELINE.11', 'G9-T1-PATTERNS-MASTERY-TOPIC-BASELINE', 11, 'G9-PAT-GENERAL-RULE', 'Which value of n makes Tn = 5n − 2 equal to 18?', '{"type":"multiple_choice","options":{"A":"3","B":"5","C":"4","D":"2"},"correct_option":"C","distractor_explanations":{"A":"Substitution gives a value 5 lower.","B":"Substitution gives a value 5 higher.","D":"Substitution gives a value 10 lower."}}', 'Set 5n − 2 = 18. Add 2 and divide by 5: n = 4.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.PAT.TOPIC-BASELINE.12', 'G9-T1-PATTERNS-MASTERY-TOPIC-BASELINE', 12, 'G9-PAT-GENERAL-RULE', 'Why is checking n = 1 important for linear pattern set 1 after finding a first difference?', '{"type":"multiple_choice","options":{"A":"It removes the need to test any term.","B":"It determines the constant term in the nth-term rule.","C":"It changes the first difference into a ratio.","D":"It proves every pattern is quadratic."},"correct_option":"B","distractor_explanations":{"A":"Checking terms validates the proposed rule.","C":"The first difference remains a difference.","D":"Many patterns with constant first differences are linear."}}', 'The first difference gives the coefficient of n. Substituting n = 1 determines the constant needed to match the first term.', 3, 'mathematical_reasoning', 'complex', 'verbal'),
  ('Q.G9.T1C.PAT.ENDLINE.1', 'G9-T1-PATTERNS-MASTERY-ENDLINE', 1, 'G9-PAT-NUMERIC-STRUCTURE', 'The pattern is 4, 7, 10, … . What is the first difference?', '{"type":"multiple_choice","options":{"A":"4","B":"6","C":"1","D":"3"},"correct_option":"D","distractor_explanations":{"A":"This is the first term, not the difference.","B":"This is the second term without its constant adjustment.","C":"This is only the constant part."}}', 'Subtract consecutive terms: (7) − (4) = 3.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.PAT.ENDLINE.2', 'G9-T1-PATTERNS-MASTERY-ENDLINE', 2, 'G9-PAT-GENERAL-RULE', 'The pattern is 6, 9, 12, … . Which rule gives Tn?', '{"type":"multiple_choice","options":{"A":"6n","B":"n + 5","C":"3n + 3","D":"3n + 6"},"correct_option":"C","distractor_explanations":{"A":"This gives the wrong first difference.","B":"This has first difference 1 rather than 3.","D":"This uses the first term as the constant without checking n = 1."}}', 'The difference is 3. Let Tn = 3n + c. At n = 1, 3 + c = 6, so c = 3.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.PAT.ENDLINE.3', 'G9-T1-PATTERNS-MASTERY-ENDLINE', 3, 'G9-PAT-NUMERIC-STRUCTURE', 'A table gives n: 1, 2, 3 and Tn: 7, 10, 13. What is T10?', '{"type":"multiple_choice","options":{"A":"40","B":"34","C":"31","D":"33"},"correct_option":"B","distractor_explanations":{"A":"This uses an unrelated constant.","C":"This omits the first-term adjustment.","D":"This omits the constant +1."}}', 'The rule is Tn = 3n + 4? Check: at n=1 this is 7; therefore T10 = 34.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.PAT.ENDLINE.4', 'G9-T1-PATTERNS-MASTERY-ENDLINE', 4, 'G9-PAT-GENERAL-RULE', 'For Tn = 4n − 2, what is T7?', '{"type":"multiple_choice","options":{"A":"26","B":"28","C":"9","D":"30"},"correct_option":"A","distractor_explanations":{"B":"This omits the −2.","C":"This adds n and the coefficient instead of multiplying.","D":"This uses +2 rather than −2."}}', 'Substitute n = 7: T7 = 4(7) − 2 = 26.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.PAT.ENDLINE.5', 'G9-T1-PATTERNS-MASTERY-ENDLINE', 5, 'G9-PAT-GEOMETRIC-VISUAL', 'A diagram in set 2 shows n joined unit squares in one row, sharing full sides. Which rule gives its matchsticks M?', '{"type":"multiple_choice","options":{"A":"M = 4n","B":"M = 3n","C":"M = n + 3","D":"M = 3n + 1"},"correct_option":"D","distractor_explanations":{"A":"This counts shared sides twice.","B":"This omits the one extra side at the end.","C":"This adds only one matchstick per additional square."}}', 'One square needs 4 matchsticks. Each additional square shares one side and adds 3. Thus M = 4 + 3(n−1) = 3n + 1.', 3, 'mathematical_reasoning', 'complex', 'verbal'),
  ('Q.G9.T1C.PAT.ENDLINE.6', 'G9-T1-PATTERNS-MASTERY-ENDLINE', 6, 'G9-PAT-GEOMETRIC-VISUAL', 'Using M = 3n + 1 for a row of joined squares, how many matchsticks are needed for n = 9?', '{"type":"multiple_choice","options":{"A":"27","B":"12","C":"28","D":"36"},"correct_option":"C","distractor_explanations":{"A":"This omits the +1.","B":"This adds rather than multiplies the figure number.","D":"This counts every square as isolated."}}', 'Substitute n = 9: M = 3(9) + 1 = 28.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.PAT.ENDLINE.7', 'G9-T1-PATTERNS-MASTERY-ENDLINE', 7, 'G9-PAT-GENERAL-RULE', 'A learner says the pattern 5, 8, 11, … has rule Tn = 3n + 5. What is the best correction?', '{"type":"multiple_choice","options":{"A":"Tn = 3n","B":"Tn = 3n + 2, because T1 must equal 5.","C":"Tn = 3n − 5","D":"Tn = 5n + 3"},"correct_option":"B","distractor_explanations":{"A":"This gives T1 = 3, so the constant is missing.","C":"At n = 1 this gives -2, not 5.","D":"This gives first difference 5, not 3."}}', 'Use Tn = 3n + c. Since T1 = 5, 3 + c = 5, so c = 2.', 3, 'mathematical_reasoning', 'complex', 'verbal'),
  ('Q.G9.T1C.PAT.ENDLINE.8', 'G9-T1-PATTERNS-MASTERY-ENDLINE', 8, 'G9-PAT-NUMERIC-STRUCTURE', 'A pattern has rule Tn = 3n + 4. Which table row is correct?', '{"type":"multiple_choice","options":{"A":"n = 3, Tn = 13","B":"n = 3, Tn = 10","C":"n = 3, Tn = 9","D":"n = 3, Tn = 5"},"correct_option":"A","distractor_explanations":{"B":"This adds the coefficient and n instead of multiplying.","C":"This omits the constant 4.","D":"This subtracts the constant instead of adding it."}}', 'Substitute n = 3: T3 = 3(3) + 4 = 13.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.PAT.ENDLINE.9', 'G9-T1-PATTERNS-MASTERY-ENDLINE', 9, 'G9-PAT-NUMERIC-STRUCTURE', 'The first differences are 3, 3, 3. What can be concluded about the sequence?', '{"type":"multiple_choice","options":{"A":"It is quadratic because it has differences.","B":"It is exponential because terms change.","C":"Its rule must be n² + c.","D":"It is linear and has an nth-term rule of the form 3n + c."},"correct_option":"D","distractor_explanations":{"A":"A constant first difference indicates a linear pattern.","B":"Exponential patterns have a constant ratio, not constant first difference.","C":"A squared rule has changing first differences."}}', 'A linear sequence changes by a constant amount. Its coefficient of n equals the constant first difference 3.', 3, 'mathematical_reasoning', 'complex', 'verbal'),
  ('Q.G9.T1C.PAT.ENDLINE.10', 'G9-T1-PATTERNS-MASTERY-ENDLINE', 10, 'G9-PAT-GEOMETRIC-VISUAL', 'Figure 1 in tile set 2 uses 6 tiles. Each new figure adds 5 tiles. Which expression gives figure n?', '{"type":"multiple_choice","options":{"A":"n + 5","B":"5n + 1","C":"6n","D":"5n + 6"},"correct_option":"B","distractor_explanations":{"A":"This adds only 1 each time.","C":"This adds 6 each time instead of 5.","D":"At n = 1 this gives 11, not 6."}}', 'Tn = 6 + 5(n−1) = 6 + 5n − 5 = 5n + 1.', 3, 'mathematical_reasoning', 'complex', 'verbal'),
  ('Q.G9.T1C.PAT.ENDLINE.11', 'G9-T1-PATTERNS-MASTERY-ENDLINE', 11, 'G9-PAT-GENERAL-RULE', 'Which value of n makes Tn = 5n − 2 equal to 23?', '{"type":"multiple_choice","options":{"A":"5","B":"3","C":"4","D":"6"},"correct_option":"A","distractor_explanations":{"B":"Substitution gives a value 10 lower.","C":"Substitution gives a value 5 lower.","D":"Substitution gives a value 5 higher."}}', 'Set 5n − 2 = 23. Add 2 and divide by 5: n = 5.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.PAT.ENDLINE.12', 'G9-T1-PATTERNS-MASTERY-ENDLINE', 12, 'G9-PAT-GENERAL-RULE', 'Why is checking n = 1 important for linear pattern set 2 after finding a first difference?', '{"type":"multiple_choice","options":{"A":"It changes the first difference into a ratio.","B":"It proves every pattern is quadratic.","C":"It removes the need to test any term.","D":"It determines the constant term in the nth-term rule."},"correct_option":"D","distractor_explanations":{"A":"The first difference remains a difference.","B":"Many patterns with constant first differences are linear.","C":"Checking terms validates the proposed rule."}}', 'The first difference gives the coefficient of n. Substituting n = 1 determines the constant needed to match the first term.', 3, 'mathematical_reasoning', 'complex', 'verbal'),
  ('Q.G9.T1C.PAT.ENDLINE.13', 'G9-T1-PATTERNS-MASTERY-ENDLINE', 13, 'G9-PAT-GEOMETRIC-VISUAL', 'A matchstick border has 9 sticks in figure 1 and increases by 3 sticks per figure. What is the rule?', '{"type":"multiple_choice","options":{"A":"9n","B":"n + 9","C":"3n + 6","D":"3n + 9"},"correct_option":"C","distractor_explanations":{"A":"This uses the first term as the common difference.","B":"This uses a first difference of 1.","D":"This uses the first term as the constant without subtracting one difference."}}', 'Tn = 9 + 3(n−1) = 3n + 6.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.PAT.ENDLINE.14', 'G9-T1-PATTERNS-MASTERY-ENDLINE', 14, 'G9-PAT-GENERAL-RULE', 'Which claim about the rule Tn = 6n + 1 is true?', '{"type":"multiple_choice","options":{"A":"The first difference is 1.","B":"Every term is odd.","C":"Every term is prime.","D":"Every term is even."},"correct_option":"B","distractor_explanations":{"A":"The first difference is 6.","C":"For n = 3, Tn = 19, which need not be prime.","D":"An even coefficient times n plus 1 is odd."}}', '6n is even for every integer n. Adding 1 produces an odd number.', 3, 'mathematical_reasoning', 'complex', 'verbal'),
  ('Q.G9.T1C.PAT.ENDLINE.15', 'G9-T1-PATTERNS-MASTERY-ENDLINE', 15, 'G9-PAT-NUMERIC-STRUCTURE', 'The pattern is 3, 6, 9, … . Which term is 18?', '{"type":"multiple_choice","options":{"A":"7","B":"5","C":"6","D":"8"},"correct_option":"A","distractor_explanations":{"B":"This gives a term three less.","C":"This gives a term equal to 3d + 6.","D":"This gives a term three more."}}', 'Tn = 3n + (3 − 3). Set 3n + 0 = 18; then 3n = 21, so n = 7.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.PAT.ENDLINE.16', 'G9-T1-PATTERNS-MASTERY-ENDLINE', 16, 'G9-PAT-GEOMETRIC-VISUAL', 'A learner in diagram set 2 counts shared sides twice in a joined-square row. Which rule will be too large?', '{"type":"multiple_choice","options":{"A":"3n + 1","B":"3n − 1","C":"n + 4","D":"4n"},"correct_option":"D","distractor_explanations":{"A":"This correctly subtracts one shared side for each added square.","B":"This is too small for a row beginning with one square.","C":"This does not count four sides per square."}}', 'Counting every square as separate gives 4n. It ignores the n−1 shared sides, so it is too large.', 3, 'mathematical_reasoning', 'complex', 'verbal'),
  ('Q.G9.T1C.PAT.MASTERY-CHALLENGE.1', 'G9-T1-PATTERNS-MASTERY-CHALLENGE', 1, 'G9-PAT-NUMERIC-STRUCTURE', 'The pattern is 5, 9, 13, … . What is the first difference?', '{"type":"multiple_choice","options":{"A":"1","B":"4","C":"5","D":"8"},"correct_option":"B","distractor_explanations":{"A":"This is only the constant part.","C":"This is the first term, not the difference.","D":"This is the second term without its constant adjustment."}}', 'Subtract consecutive terms: (9) − (5) = 4.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.PAT.MASTERY-CHALLENGE.2', 'G9-T1-PATTERNS-MASTERY-CHALLENGE', 2, 'G9-PAT-GENERAL-RULE', 'The pattern is 7, 11, 15, … . Which rule gives Tn?', '{"type":"multiple_choice","options":{"A":"4n + 3","B":"4n + 7","C":"7n","D":"n + 6"},"correct_option":"A","distractor_explanations":{"B":"This uses the first term as the constant without checking n = 1.","C":"This gives the wrong first difference.","D":"This has first difference 1 rather than 4."}}', 'The difference is 4. Let Tn = 4n + c. At n = 1, 4 + c = 7, so c = 3.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.PAT.MASTERY-CHALLENGE.3', 'G9-T1-PATTERNS-MASTERY-CHALLENGE', 3, 'G9-PAT-NUMERIC-STRUCTURE', 'A table gives n: 1, 2, 3 and Tn: 9, 13, 17. What is T10?', '{"type":"multiple_choice","options":{"A":"41","B":"44","C":"50","D":"45"},"correct_option":"D","distractor_explanations":{"A":"This omits the first-term adjustment.","B":"This omits the constant +1.","C":"This uses an unrelated constant."}}', 'The rule is Tn = 4n + 5? Check: at n=1 this is 9; therefore T10 = 45.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.PAT.MASTERY-CHALLENGE.4', 'G9-T1-PATTERNS-MASTERY-CHALLENGE', 4, 'G9-PAT-GENERAL-RULE', 'For Tn = 5n − 2, what is T8?', '{"type":"multiple_choice","options":{"A":"11","B":"42","C":"38","D":"40"},"correct_option":"C","distractor_explanations":{"A":"This adds n and the coefficient instead of multiplying.","B":"This uses +2 rather than −2.","D":"This omits the −2."}}', 'Substitute n = 8: T8 = 5(8) − 2 = 38.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.PAT.MASTERY-CHALLENGE.5', 'G9-T1-PATTERNS-MASTERY-CHALLENGE', 5, 'G9-PAT-GEOMETRIC-VISUAL', 'A diagram in set 3 shows n joined unit squares in one row, sharing full sides. Which rule gives its matchsticks M?', '{"type":"multiple_choice","options":{"A":"M = n + 3","B":"M = 3n + 1","C":"M = 4n","D":"M = 3n"},"correct_option":"B","distractor_explanations":{"A":"This adds only one matchstick per additional square.","C":"This counts shared sides twice.","D":"This omits the one extra side at the end."}}', 'One square needs 4 matchsticks. Each additional square shares one side and adds 3. Thus M = 4 + 3(n−1) = 3n + 1.', 3, 'mathematical_reasoning', 'complex', 'verbal'),
  ('Q.G9.T1C.PAT.MASTERY-CHALLENGE.6', 'G9-T1-PATTERNS-MASTERY-CHALLENGE', 6, 'G9-PAT-GEOMETRIC-VISUAL', 'Using M = 3n + 1 for a row of joined squares, how many matchsticks are needed for n = 10?', '{"type":"multiple_choice","options":{"A":"31","B":"40","C":"30","D":"13"},"correct_option":"A","distractor_explanations":{"B":"This counts every square as isolated.","C":"This omits the +1.","D":"This adds rather than multiplies the figure number."}}', 'Substitute n = 10: M = 3(10) + 1 = 31.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.PAT.MASTERY-CHALLENGE.7', 'G9-T1-PATTERNS-MASTERY-CHALLENGE', 7, 'G9-PAT-GENERAL-RULE', 'A learner says the pattern 6, 9, 12, … has rule Tn = 3n + 6. What is the best correction?', '{"type":"multiple_choice","options":{"A":"Tn = 3n − 6","B":"Tn = 6n + 3","C":"Tn = 3n","D":"Tn = 3n + 3, because T1 must equal 6."},"correct_option":"D","distractor_explanations":{"A":"At n = 1 this gives -3, not 6.","B":"This gives first difference 6, not 3.","C":"This gives T1 = 3, so the constant is missing."}}', 'Use Tn = 3n + c. Since T1 = 6, 3 + c = 6, so c = 3.', 3, 'mathematical_reasoning', 'complex', 'verbal'),
  ('Q.G9.T1C.PAT.MASTERY-CHALLENGE.8', 'G9-T1-PATTERNS-MASTERY-CHALLENGE', 8, 'G9-PAT-NUMERIC-STRUCTURE', 'A pattern has rule Tn = 4n + 4. Which table row is correct?', '{"type":"multiple_choice","options":{"A":"n = 3, Tn = 12","B":"n = 3, Tn = 8","C":"n = 3, Tn = 16","D":"n = 3, Tn = 11"},"correct_option":"C","distractor_explanations":{"A":"This omits the constant 4.","B":"This subtracts the constant instead of adding it.","D":"This adds the coefficient and n instead of multiplying."}}', 'Substitute n = 3: T3 = 4(3) + 4 = 16.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.PAT.MASTERY-CHALLENGE.9', 'G9-T1-PATTERNS-MASTERY-CHALLENGE', 9, 'G9-PAT-NUMERIC-STRUCTURE', 'The first differences are 4, 4, 4. What can be concluded about the sequence?', '{"type":"multiple_choice","options":{"A":"Its rule must be n² + c.","B":"It is linear and has an nth-term rule of the form 4n + c.","C":"It is quadratic because it has differences.","D":"It is exponential because terms change."},"correct_option":"B","distractor_explanations":{"A":"A squared rule has changing first differences.","C":"A constant first difference indicates a linear pattern.","D":"Exponential patterns have a constant ratio, not constant first difference."}}', 'A linear sequence changes by a constant amount. Its coefficient of n equals the constant first difference 4.', 3, 'mathematical_reasoning', 'complex', 'verbal'),
  ('Q.G9.T1C.PAT.MASTERY-CHALLENGE.10', 'G9-T1-PATTERNS-MASTERY-CHALLENGE', 10, 'G9-PAT-GEOMETRIC-VISUAL', 'Figure 1 in tile set 3 uses 7 tiles. Each new figure adds 6 tiles. Which expression gives figure n?', '{"type":"multiple_choice","options":{"A":"7n","B":"6n + 7","C":"n + 6","D":"6n + 1"},"correct_option":"D","distractor_explanations":{"A":"This adds 7 each time instead of 6.","B":"At n = 1 this gives 13, not 7.","C":"This adds only 1 each time."}}', 'Tn = 7 + 6(n−1) = 7 + 6n − 6 = 6n + 1.', 3, 'mathematical_reasoning', 'complex', 'verbal'),
  ('Q.G9.T1C.PAT.MASTERY-CHALLENGE.11', 'G9-T1-PATTERNS-MASTERY-CHALLENGE', 11, 'G9-PAT-GENERAL-RULE', 'Which value of n makes Tn = 5n − 2 equal to 28?', '{"type":"multiple_choice","options":{"A":"5","B":"7","C":"6","D":"4"},"correct_option":"C","distractor_explanations":{"A":"Substitution gives a value 5 lower.","B":"Substitution gives a value 5 higher.","D":"Substitution gives a value 10 lower."}}', 'Set 5n − 2 = 28. Add 2 and divide by 5: n = 6.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.PAT.MASTERY-CHALLENGE.12', 'G9-T1-PATTERNS-MASTERY-CHALLENGE', 12, 'G9-PAT-GENERAL-RULE', 'Why is checking n = 1 important for linear pattern set 3 after finding a first difference?', '{"type":"multiple_choice","options":{"A":"It removes the need to test any term.","B":"It determines the constant term in the nth-term rule.","C":"It changes the first difference into a ratio.","D":"It proves every pattern is quadratic."},"correct_option":"B","distractor_explanations":{"A":"Checking terms validates the proposed rule.","C":"The first difference remains a difference.","D":"Many patterns with constant first differences are linear."}}', 'The first difference gives the coefficient of n. Substituting n = 1 determines the constant needed to match the first term.', 3, 'mathematical_reasoning', 'complex', 'verbal'),
  ('Q.G9.T1C.PAT.MASTERY-CHALLENGE.13', 'G9-T1-PATTERNS-MASTERY-CHALLENGE', 13, 'G9-PAT-GEOMETRIC-VISUAL', 'A matchstick border has 11 sticks in figure 1 and increases by 4 sticks per figure. What is the rule?', '{"type":"multiple_choice","options":{"A":"4n + 7","B":"4n + 11","C":"11n","D":"n + 11"},"correct_option":"A","distractor_explanations":{"B":"This uses the first term as the constant without subtracting one difference.","C":"This uses the first term as the common difference.","D":"This uses a first difference of 1."}}', 'Tn = 11 + 4(n−1) = 4n + 7.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.PAT.MASTERY-CHALLENGE.14', 'G9-T1-PATTERNS-MASTERY-CHALLENGE', 14, 'G9-PAT-GENERAL-RULE', 'Which claim about the rule Tn = 8n + 1 is true?', '{"type":"multiple_choice","options":{"A":"Every term is prime.","B":"Every term is even.","C":"The first difference is 1.","D":"Every term is odd."},"correct_option":"D","distractor_explanations":{"A":"For n = 4, Tn = 33, which need not be prime.","B":"An even coefficient times n plus 1 is odd.","C":"The first difference is 8."}}', '8n is even for every integer n. Adding 1 produces an odd number.', 3, 'mathematical_reasoning', 'complex', 'verbal'),
  ('Q.G9.T1C.PAT.MASTERY-CHALLENGE.15', 'G9-T1-PATTERNS-MASTERY-CHALLENGE', 15, 'G9-PAT-NUMERIC-STRUCTURE', 'The pattern is 4, 7, 10, … . Which term is 21?', '{"type":"multiple_choice","options":{"A":"7","B":"9","C":"8","D":"6"},"correct_option":"C","distractor_explanations":{"A":"This gives a term equal to 3d + 6.","B":"This gives a term three more.","D":"This gives a term three less."}}', 'Tn = 3n + (4 − 3). Set 3n + 1 = 21; then 3n = 24, so n = 8.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.PAT.MASTERY-CHALLENGE.16', 'G9-T1-PATTERNS-MASTERY-CHALLENGE', 16, 'G9-PAT-GEOMETRIC-VISUAL', 'A learner in diagram set 3 counts shared sides twice in a joined-square row. Which rule will be too large?', '{"type":"multiple_choice","options":{"A":"n + 4","B":"4n","C":"3n + 1","D":"3n − 1"},"correct_option":"B","distractor_explanations":{"A":"This does not count four sides per square.","C":"This correctly subtracts one shared side for each added square.","D":"This is too small for a row beginning with one square."}}', 'Counting every square as separate gives 4n. It ignores the n−1 shared sides, so it is too large.', 3, 'mathematical_reasoning', 'complex', 'verbal'),
  ('Q.G9.T1C.PAT.ENDLINE-REASSESSMENT-B.1', 'G9-T1-PATTERNS-MASTERY-ENDLINE-REASSESSMENT-B', 1, 'G9-PAT-NUMERIC-STRUCTURE', 'The pattern is 6, 11, 16, … . What is the first difference?', '{"type":"multiple_choice","options":{"A":"5","B":"6","C":"10","D":"1"},"correct_option":"A","distractor_explanations":{"B":"This is the first term, not the difference.","C":"This is the second term without its constant adjustment.","D":"This is only the constant part."}}', 'Subtract consecutive terms: (11) − (6) = 5.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.PAT.ENDLINE-REASSESSMENT-B.2', 'G9-T1-PATTERNS-MASTERY-ENDLINE-REASSESSMENT-B', 2, 'G9-PAT-GENERAL-RULE', 'The pattern is 8, 13, 18, … . Which rule gives Tn?', '{"type":"multiple_choice","options":{"A":"5n + 8","B":"8n","C":"n + 7","D":"5n + 3"},"correct_option":"D","distractor_explanations":{"A":"This uses the first term as the constant without checking n = 1.","B":"This gives the wrong first difference.","C":"This has first difference 1 rather than 5."}}', 'The difference is 5. Let Tn = 5n + c. At n = 1, 5 + c = 8, so c = 3.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.PAT.ENDLINE-REASSESSMENT-B.3', 'G9-T1-PATTERNS-MASTERY-ENDLINE-REASSESSMENT-B', 3, 'G9-PAT-NUMERIC-STRUCTURE', 'A table gives n: 1, 2, 3 and Tn: 11, 16, 21. What is T10?', '{"type":"multiple_choice","options":{"A":"55","B":"60","C":"56","D":"51"},"correct_option":"C","distractor_explanations":{"A":"This omits the constant +1.","B":"This uses an unrelated constant.","D":"This omits the first-term adjustment."}}', 'The rule is Tn = 5n + 6? Check: at n=1 this is 11; therefore T10 = 56.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.PAT.ENDLINE-REASSESSMENT-B.4', 'G9-T1-PATTERNS-MASTERY-ENDLINE-REASSESSMENT-B', 4, 'G9-PAT-GENERAL-RULE', 'For Tn = 6n − 2, what is T9?', '{"type":"multiple_choice","options":{"A":"56","B":"52","C":"54","D":"13"},"correct_option":"B","distractor_explanations":{"A":"This uses +2 rather than −2.","C":"This omits the −2.","D":"This adds n and the coefficient instead of multiplying."}}', 'Substitute n = 9: T9 = 6(9) − 2 = 52.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.PAT.ENDLINE-REASSESSMENT-B.5', 'G9-T1-PATTERNS-MASTERY-ENDLINE-REASSESSMENT-B', 5, 'G9-PAT-GEOMETRIC-VISUAL', 'A diagram in set 4 shows n joined unit squares in one row, sharing full sides. Which rule gives its matchsticks M?', '{"type":"multiple_choice","options":{"A":"M = 3n + 1","B":"M = 4n","C":"M = 3n","D":"M = n + 3"},"correct_option":"A","distractor_explanations":{"B":"This counts shared sides twice.","C":"This omits the one extra side at the end.","D":"This adds only one matchstick per additional square."}}', 'One square needs 4 matchsticks. Each additional square shares one side and adds 3. Thus M = 4 + 3(n−1) = 3n + 1.', 3, 'mathematical_reasoning', 'complex', 'verbal'),
  ('Q.G9.T1C.PAT.ENDLINE-REASSESSMENT-B.6', 'G9-T1-PATTERNS-MASTERY-ENDLINE-REASSESSMENT-B', 6, 'G9-PAT-GEOMETRIC-VISUAL', 'Using M = 3n + 1 for a row of joined squares, how many matchsticks are needed for n = 11?', '{"type":"multiple_choice","options":{"A":"44","B":"33","C":"14","D":"34"},"correct_option":"D","distractor_explanations":{"A":"This counts every square as isolated.","B":"This omits the +1.","C":"This adds rather than multiplies the figure number."}}', 'Substitute n = 11: M = 3(11) + 1 = 34.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.PAT.ENDLINE-REASSESSMENT-B.7', 'G9-T1-PATTERNS-MASTERY-ENDLINE-REASSESSMENT-B', 7, 'G9-PAT-GENERAL-RULE', 'A learner says the pattern 7, 10, 13, … has rule Tn = 3n + 7. What is the best correction?', '{"type":"multiple_choice","options":{"A":"Tn = 7n + 3","B":"Tn = 3n","C":"Tn = 3n + 4, because T1 must equal 7.","D":"Tn = 3n − 7"},"correct_option":"C","distractor_explanations":{"A":"This gives first difference 7, not 3.","B":"This gives T1 = 3, so the constant is missing.","D":"At n = 1 this gives -4, not 7."}}', 'Use Tn = 3n + c. Since T1 = 7, 3 + c = 7, so c = 4.', 3, 'mathematical_reasoning', 'complex', 'verbal'),
  ('Q.G9.T1C.PAT.ENDLINE-REASSESSMENT-B.8', 'G9-T1-PATTERNS-MASTERY-ENDLINE-REASSESSMENT-B', 8, 'G9-PAT-NUMERIC-STRUCTURE', 'A pattern has rule Tn = 5n + 4. Which table row is correct?', '{"type":"multiple_choice","options":{"A":"n = 3, Tn = 11","B":"n = 3, Tn = 19","C":"n = 3, Tn = 12","D":"n = 3, Tn = 15"},"correct_option":"B","distractor_explanations":{"A":"This subtracts the constant instead of adding it.","C":"This adds the coefficient and n instead of multiplying.","D":"This omits the constant 4."}}', 'Substitute n = 3: T3 = 5(3) + 4 = 19.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.PAT.ENDLINE-REASSESSMENT-B.9', 'G9-T1-PATTERNS-MASTERY-ENDLINE-REASSESSMENT-B', 9, 'G9-PAT-NUMERIC-STRUCTURE', 'The first differences are 5, 5, 5. What can be concluded about the sequence?', '{"type":"multiple_choice","options":{"A":"It is linear and has an nth-term rule of the form 5n + c.","B":"It is quadratic because it has differences.","C":"It is exponential because terms change.","D":"Its rule must be n² + c."},"correct_option":"A","distractor_explanations":{"B":"A constant first difference indicates a linear pattern.","C":"Exponential patterns have a constant ratio, not constant first difference.","D":"A squared rule has changing first differences."}}', 'A linear sequence changes by a constant amount. Its coefficient of n equals the constant first difference 5.', 3, 'mathematical_reasoning', 'complex', 'verbal'),
  ('Q.G9.T1C.PAT.ENDLINE-REASSESSMENT-B.10', 'G9-T1-PATTERNS-MASTERY-ENDLINE-REASSESSMENT-B', 10, 'G9-PAT-GEOMETRIC-VISUAL', 'Figure 1 in tile set 4 uses 8 tiles. Each new figure adds 7 tiles. Which expression gives figure n?', '{"type":"multiple_choice","options":{"A":"7n + 1","B":"8n","C":"7n + 8","D":"n + 7"},"correct_option":"A","distractor_explanations":{"B":"This adds 8 each time instead of 7.","C":"At n = 1 this gives 15, not 8.","D":"This adds only 1 each time."}}', 'Tn = 8 + 7(n−1) = 8 + 7n − 7 = 7n + 1.', 3, 'mathematical_reasoning', 'complex', 'verbal'),
  ('Q.G9.T1C.PAT.ENDLINE-REASSESSMENT-B.11', 'G9-T1-PATTERNS-MASTERY-ENDLINE-REASSESSMENT-B', 11, 'G9-PAT-GENERAL-RULE', 'Which value of n makes Tn = 5n − 2 equal to 33?', '{"type":"multiple_choice","options":{"A":"5","B":"6","C":"8","D":"7"},"correct_option":"D","distractor_explanations":{"A":"Substitution gives a value 10 lower.","B":"Substitution gives a value 5 lower.","C":"Substitution gives a value 5 higher."}}', 'Set 5n − 2 = 33. Add 2 and divide by 5: n = 7.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.PAT.ENDLINE-REASSESSMENT-B.12', 'G9-T1-PATTERNS-MASTERY-ENDLINE-REASSESSMENT-B', 12, 'G9-PAT-GENERAL-RULE', 'Why is checking n = 1 important for linear pattern set 4 after finding a first difference?', '{"type":"multiple_choice","options":{"A":"It proves every pattern is quadratic.","B":"It removes the need to test any term.","C":"It determines the constant term in the nth-term rule.","D":"It changes the first difference into a ratio."},"correct_option":"C","distractor_explanations":{"A":"Many patterns with constant first differences are linear.","B":"Checking terms validates the proposed rule.","D":"The first difference remains a difference."}}', 'The first difference gives the coefficient of n. Substituting n = 1 determines the constant needed to match the first term.', 3, 'mathematical_reasoning', 'complex', 'verbal'),
  ('Q.G9.T1C.PAT.ENDLINE-REASSESSMENT-B.13', 'G9-T1-PATTERNS-MASTERY-ENDLINE-REASSESSMENT-B', 13, 'G9-PAT-GEOMETRIC-VISUAL', 'A matchstick border has 13 sticks in figure 1 and increases by 5 sticks per figure. What is the rule?', '{"type":"multiple_choice","options":{"A":"n + 13","B":"5n + 8","C":"5n + 13","D":"13n"},"correct_option":"B","distractor_explanations":{"A":"This uses a first difference of 1.","C":"This uses the first term as the constant without subtracting one difference.","D":"This uses the first term as the common difference."}}', 'Tn = 13 + 5(n−1) = 5n + 8.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.PAT.ENDLINE-REASSESSMENT-B.14', 'G9-T1-PATTERNS-MASTERY-ENDLINE-REASSESSMENT-B', 14, 'G9-PAT-GENERAL-RULE', 'Which claim about the rule Tn = 10n + 1 is true?', '{"type":"multiple_choice","options":{"A":"Every term is odd.","B":"Every term is prime.","C":"Every term is even.","D":"The first difference is 1."},"correct_option":"A","distractor_explanations":{"B":"For n = 5, Tn = 51, which need not be prime.","C":"An even coefficient times n plus 1 is odd.","D":"The first difference is 10."}}', '10n is even for every integer n. Adding 1 produces an odd number.', 3, 'mathematical_reasoning', 'complex', 'verbal'),
  ('Q.G9.T1C.PAT.ENDLINE-REASSESSMENT-B.15', 'G9-T1-PATTERNS-MASTERY-ENDLINE-REASSESSMENT-B', 15, 'G9-PAT-NUMERIC-STRUCTURE', 'The pattern is 5, 8, 11, … . Which term is 24?', '{"type":"multiple_choice","options":{"A":"7","B":"8","C":"10","D":"9"},"correct_option":"D","distractor_explanations":{"A":"This gives a term three less.","B":"This gives a term equal to 3d + 6.","C":"This gives a term three more."}}', 'Tn = 3n + (5 − 3). Set 3n + 2 = 24; then 3n = 27, so n = 9.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.PAT.ENDLINE-REASSESSMENT-B.16', 'G9-T1-PATTERNS-MASTERY-ENDLINE-REASSESSMENT-B', 16, 'G9-PAT-GEOMETRIC-VISUAL', 'A learner in diagram set 4 counts shared sides twice in a joined-square row. Which rule will be too large?', '{"type":"multiple_choice","options":{"A":"3n − 1","B":"n + 4","C":"4n","D":"3n + 1"},"correct_option":"C","distractor_explanations":{"A":"This is too small for a row beginning with one square.","B":"This does not count four sides per square.","D":"This correctly subtracts one shared side for each added square."}}', 'Counting every square as separate gives 4n. It ignores the n−1 shared sides, so it is too large.', 3, 'mathematical_reasoning', 'complex', 'verbal'),
  ('Q.G9.T1C.ENTRY.PAT.1', 'G9-T1-ENTRY-BASELINE-A', 10, 'G9-PAT-GENERAL-RULE', 'For Tn = 7n − 2, what is T10?', '{"type":"multiple_choice","options":{"A":"68","B":"70","C":"15","D":"72"},"correct_option":"A","distractor_explanations":{"B":"This omits the −2.","C":"This adds n and the coefficient instead of multiplying.","D":"This uses +2 rather than −2."}}', 'Substitute n = 10: T10 = 7(10) − 2 = 68.', 2, 'procedural', 'routine', 'symbolic'),
  ('Q.G9.T1C.ENTRY.PAT.2', 'G9-T1-ENTRY-BASELINE-A', 11, 'G9-PAT-GEOMETRIC-VISUAL', 'A diagram in set 5 shows n joined unit squares in one row, sharing full sides. Which rule gives its matchsticks M?', '{"type":"multiple_choice","options":{"A":"M = 4n","B":"M = 3n","C":"M = n + 3","D":"M = 3n + 1"},"correct_option":"D","distractor_explanations":{"A":"This counts shared sides twice.","B":"This omits the one extra side at the end.","C":"This adds only one matchstick per additional square."}}', 'One square needs 4 matchsticks. Each additional square shares one side and adds 3. Thus M = 4 + 3(n−1) = 3n + 1.', 3, 'mathematical_reasoning', 'complex', 'verbal'),
  ('Q.G9.T1C.ENTRY.PAT.3', 'G9-T1-ENTRY-BASELINE-A', 12, 'G9-PAT-GEOMETRIC-VISUAL', 'Using M = 3n + 1 for a row of joined squares, how many matchsticks are needed for n = 12?', '{"type":"multiple_choice","options":{"A":"36","B":"15","C":"37","D":"48"},"correct_option":"C","distractor_explanations":{"A":"This omits the +1.","B":"This adds rather than multiplies the figure number.","D":"This counts every square as isolated."}}', 'Substitute n = 12: M = 3(12) + 1 = 37.', 2, 'procedural', 'routine', 'symbolic');

insert into public.question_versions(
  question_item_id, version_number, review_status, activity_type, cognitive_level,
  representation, difficulty, reasoning_classification, calculator_policy, prompt,
  answer_config, solution, marks, material_change_note
)
select item.id, 1, 'draft', 'independent_practice',
  content.cognitive_level::public.caps_cognitive_level,
  content.representation::public.math_representation, content.difficulty,
  content.reasoning_classification, 'not_allowed', content.prompt,
  content.answer_config::jsonb, content.solution, 1,
  'Content reconstruction v1: corrected original formal-assessment item; independent mathematical review remains required before publication.'
from grade9_term1_reconstructed_content content
join public.question_items item on item.item_code = content.item_code
left join public.question_versions version
  on version.question_item_id = item.id and version.version_number = 1
where version.id is null;

do $$
declare v_missing integer;
begin
  select count(*) into v_missing
  from grade9_term1_reconstructed_content content
  left join public.question_items item on item.item_code = content.item_code
  left join public.question_versions version
    on version.question_item_id = item.id and version.version_number = 1
  where version.id is null;
  if v_missing > 0 then
    raise exception 'grade9_term1_reconstruction_question_versions_missing: %', v_missing
      using errcode = '23514';
  end if;
end;
$$;

insert into public.question_version_skill_links(question_version_id, skill_id, relationship_type)
select version.id, skill.id, 'primary'
from grade9_term1_reconstructed_content content
join public.question_items item on item.item_code = content.item_code
join public.question_versions version
  on version.question_item_id = item.id and version.version_number = 1
join public.curriculum_skills skill on skill.skill_code = content.skill_code
on conflict (question_version_id, skill_id) do nothing;

insert into public.learning_assessment_definition_questions(
  learning_assessment_definition_id, question_version_id, display_order
)
select definition.id, version.id, content.display_order
from grade9_term1_reconstructed_content content
join public.learning_assessment_definitions definition on definition.code = content.definition_code
join public.question_items item on item.item_code = content.item_code
join public.question_versions version
  on version.question_item_id = item.id and version.version_number = 1
where definition.review_status in ('draft', 'rejected')
on conflict (learning_assessment_definition_id, question_version_id)
  do update set display_order = excluded.display_order;
